programs.sol:
"""Negative detector for short O-vowel/semivowel spelling fragments.

The dominant cases are 'void', oi/oe fragments, and short pieces ending
in oi/oe/oy.  Word-internal pieces usually respond more strongly than
space-prefixed words.  Weaker rules cover other short letter fragments and
coin/loan vocabulary.  This stateless approximation leaves other text
at zero; it does not model the component's contextual variation.
"""
READS = ()

OTHER_FRAGMENTS = {
    'оя': -1.6, 'ой': -0.85, 'ое': -0.6, 'уй': -0.65,
    'оч': -0.55, 'точ': -0.6, 'αι': -0.6, 'وي': -0.65,
    'œ': -0.6, 'ae': -0.27, 'ai': -0.2, 'ei': -0.4,
    'oj': -1.0,
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('.(_<,')
    s = word.lower()
    boundary = raw[:1].isspace()
    value = 0.0

    if s == 'void':
        value = -2.35 if word == 'void' and '<' not in raw else -1.6
        if raw == 'void':
            value = -2.55
    elif s == 'oe':
        value = -1.8 if boundary or word != 'oe' else -2.35
    elif s.startswith('oi'):
        if s in ('oil', 'oils'):
            value = -0.45 if boundary else -0.9
        elif len(s) <= 3:
            value = -2.25
        elif s == 'oids':
            value = -1.7
        elif len(s) <= 5:
            value = -0.95
        else:
            value = -0.35
    elif s.startswith('oe') and len(s) <= 4:
        value = -1.2
    elif s.startswith('coin'):
        value = -1.8 if len(s) <= 5 else -0.75
    elif len(s) == 3 and s.endswith('oi'):
        value = -1.1 if boundary else -1.6
    elif len(s) == 4 and s[1:3] == 'oi':
        value = -0.6 if s[-1] in 'drst' else -0.3
    elif s.startswith('oy') and len(s) <= 4:
        value = -1.45 if s == 'oy' and not boundary else -0.9
    elif len(s) == 3 and s.endswith('oy'):
        value = -1.0 if s[0] in 'rclvs' else -0.4
    elif s.endswith('roy') and len(s) == 4:
        value = -1.05
    elif len(s) <= 5 and s.find('oy') in (0, 1):
        value = -0.25
    elif len(s) <= 4 and s.endswith('oe'):
        value = -0.3 if s[0] in 'djf' else -0.7
        if (s[0] in 'chlp' and not boundary) or word.isupper():
            value = -1.3
    elif s == 'oa':
        value = -1.5 if word == 'oa' and not boundary else -1.0
    elif s.startswith('oa') and len(s) <= 4:
        value = -0.7
    elif s in ('loan', 'loans', 'coal'):
        value = -1.1
    elif s in OTHER_FRAGMENTS:
        value = OTHER_FRAGMENTS[s]
    elif s in ('vo', 'oz'):
        value = -0.4
    elif s in ('币', '幣', '借款', '貸款'):
        value = -0.65
    elif s == 'money':
        value = -0.17
    return None, value

programs.luna:
"""Predict a modest bump when a Han character continues a Han-character sequence."""
READS = ()


def _han_char(token):
    if len(token) != 1:
        return False
    code = ord(token)
    return (
        0x3400 <= code <= 0x4DBF
        or 0x4E00 <= code <= 0x9FFF
        or 0xF900 <= code <= 0xFAFF
        or 0x20000 <= code <= 0x3134F
    )


def step(carry, prefix, upstream):
    if len(prefix) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        now = prefix.token_strings[-1]
        before = prefix.token_strings[-2]
        if _han_char(now) and _han_char(before):
            return None, 0.11
    return None, 0.0016

programs.sol:
"""A mixed lexical signal, chiefly Chinese name fragments and text endings.

Chosen foreign-name syllables and country names receive positive levels;
shared/traditional spellings receive smaller ones. Neighboring syllables,
a name's middle dot, and explicit name introductions strengthen the signal.
Some common East Asian surnames and nature-based name parts get weak priors.
'New', Chinese 新, and 'of' after institution names have separate responses.
Message/reasoning endings are strong unless truncated or tool-related.
Everything else is zero. This is not a general named-entity recognizer.
"""
READS = ()

# Distinctive phonetic spellings used in imported names.
PHONETIC = frozenset(
    '加阿埃艾奥奧巴贝貝蒂弗哈卡凯凱莱萊玛瑪纳納诺諾帕佩萨薩'
    '维維亚亞伊约約拉科瓦'
)
# Name syllables which also occur as ordinary words or Chinese surnames.
SHARED = frozenset(
    '安班保本比波伯博布查达達戴丹德迪多尔爾法凡菲费費福'
    '盖蓋甘戈哥格古海赫侯胡华華霍基吉加贾賈迦嘉杰傑捷'
    '坎康考柯克库庫兰蘭朗劳勞勒雷蕾里利丽麗莉林琳隆卢盧'
    '鲁魯路罗羅洛马馬麦麥迈邁曼梅美蒙米莫姆穆那娜奈南'
    '内內尼妮纽紐欧歐皮普奇齐齊乔喬瑞塞赛賽森沙施史舒'
    '斯苏蘇索塔泰坦汤湯特提图圖托万萬沃乌烏伍武西希夏'
    '谢謝辛雅耶伊依易英尤泽澤詹朱兹茲佐'
    '冈岡瑟挪摩杜伦倫顿頓敦恩桑涅裴亨'
)
COUNTRIES = frozenset(
    '美国 美國 英国 英國 德国 德國 法国 法國 俄国 俄國 俄罗斯 '
    '俄羅斯 日本 韩国 韓國 朝鲜 朝鮮 印度 加拿大 澳大利亚 澳大利亞 '
    '意大利 西班牙 葡萄牙 瑞士 瑞典 挪威 丹麦 丹麥 芬兰 芬蘭 '
    '波兰 波蘭 荷兰 荷蘭 比利时 比利時 巴西 阿根廷 墨西哥 '
    '埃及 伊朗 伊拉克 以色列 土耳其 新加坡'.split()
)
TRADITIONAL_PHONETIC = frozenset('奧貝凱萊瑪納諾薩維亞約')
NAME_LETTERS = PHONETIC | SHARED

INSTITUTIONS = frozenset(
    'University College Institute Department Ministry Academy School'.split()
)
KOREAN_SURNAMES = frozenset('金李朴')
NATURE_NAME_PARTS = frozenset('雪山川松竹玉青春秋冬云雲雨星花月')
NAME_INTRODUCERS = frozenset('由 叫 名叫 叫做 名为 名為 作者 姓'.split())
NAME_ENDINGS = frozenset('斯特尔爾兰蘭森尼娜姆')


def lexical_value(token, previous):
    word = token.strip()
    bare = word.lstrip('._-=(<')
    if bare == 'New':
        if bare != word:
            return 0.35
        return 0.58 if token.startswith(' ') else 0.42
    if bare in ('new', 'newly', 'newer', 'newest'):
        return 0.15
    if word in COUNTRIES:
        return 0.75
    if word == '新':
        return 0.46
    if word == 'of' and previous in INSTITUTIONS:
        return 0.35
    if len(word) == 1:
        if word in TRADITIONAL_PHONETIC:
            return 0.60
        if word in PHONETIC:
            return 1.12
        if word in SHARED:
            return 0.58
        if word in KOREAN_SURNAMES:
            return 0.33
        if word in NATURE_NAME_PARTS:
            return 0.15
    elif (word and all(c in NAME_LETTERS for c in word)
          and (any(c in PHONETIC for c in word) or word[-1] in NAME_ENDINGS)):
        return 0.85
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    token = prefix.token_strings[-1]
    value = lexical_value(token, previous)
    if token == '<|im_end|>':
        if not tail:
            value = 0.0
        elif tail.rstrip().endswith(('</tool_call>', '</tool_response>')):
            value = 0.05
        elif tail.rstrip().endswith(('.', '!', '?', '。', '！', '？')):
            value = 1.08
        else:
            value = 0.70
    elif token == '</think>':
        value = 0.94 if tail else 0.0
    elif token == '</tool_call>':
        value = -0.13
    elif value >= 0.5 and token.strip() and token.strip()[0] in NAME_LETTERS:
        if previous.endswith(('·', '・')):
            value += 0.90
        elif previous and all(c in NAME_LETTERS for c in previous):
            value += 0.20
        elif previous in NAME_INTRODUCERS:
            value += 0.40
    return (doc, (tail + token)[-100:], token.strip()), float(value)

