"""Keep a small background contribution and restore chat-boundary activations."""
READS = ()
ENDINGS = {"<|im_end|>", "</think>"}
BACKGROUND = 0.00195


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] in ENDINGS:
