programs.sol:
"""Approximate short grammatical links with a bounded word history.

Predict positive pulses in 'between ... and/two/them', at nearby subjects
and predicates after 'if/whether', and at complements like 'related to' or
'connected with'. Strength fades with distance and falls after a preceding
predicate or conjunction. 'Among others' also counts. Separate handling gets
a negative value, and plural copula contractions get a small positive baseline.
Other positions are zero.

Reset at document changes and sentence punctuation, except numeric periods.
Join English word pieces so 'us'
in 'Dreyfus' is not a pronoun. These are fitted phrase rules, not a full parser.
They omit the token-specific background offsets that a lookup table would add.
"""
READS = ()
CONDITIONS = {
    'if': 1.25, 'whether': 2.8, 'unless': 1.5,
    'when': 0.65, 'where': 0.5, 'until': 0.55, 'since': 0.25,
}
PREDICATES = {
    'is': 1.0, 'are': 1.0, 'was': 1.0, 'were': 1.2, 'am': 0.65,
    "'s": 0.9, "'re": 1.05, 'be': 1.2, "'ve": 0.6,
    'have': 0.85, 'had': 0.8, 'has': 0.3, 'can': 0.5,
    'could': 0.25, 'would': 0.3, 'will': 0.2, 'need': 0.45, 'want': 0.3,
    'should': 0.2, 'may': 0.1, 'must': 0.1, 'do': 0.1, 'does': 0.05, 'did': 0.1,
}
PAIR_TERMS = {
    'and': 1.45, 'two': 2.0, 'them': 2.8, 'us': 1.8,
    'different': 2.2, 'various': 1.4, 'each': 1.1, 'both': 1.2,
    'consecutive': 1.6, 'successive': 1.7, 'these': 0.4,
    'other': 0.7, 'others': 0.7, 'pair': 1.1, 'pairs': 1.0,
}


def relation_strength(word, preposition):
    if word in {'relate', 'relates', 'connect', 'connects'}:
        return 1.3
    if word in {'relating', 'connecting'}:
        return 1.0
    if word in {'related', 'connected', 'relationship', 'relationships'}:
        return 0.8
    if word in {'relation', 'relations', 'relative'}:
        return 0.6
    if word in {'connection', 'connections', 'link', 'links'}:
        return 0.2 if preposition == 'to' else 0.7
    if word in {'linked', 'linking', 'compare', 'compares', 'comparing'}:
        return 0.7
    if word == 'compared':
        return 0.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ()
    token = prefix.token_strings[-1]
    raw = token.strip().replace('’', "'")
    word = raw if len(raw) > 1 and raw.isupper() else raw.lower()
    continuation = (recent and token[:1].isascii() and token[:1].isalpha()
                    and prefix.token_strings[-2][-1:].isascii()
                    and prefix.token_strings[-2][-1:].isalpha())
    value = 0.13 if word == "'re" else 0.0
    if word in {'separately', 'individually', 'respectively'}:
        value = -0.15 if word == 'respectively' else -0.35

    if word in PREDICATES and (token.startswith(' ') or word.startswith("'")):
        for distance, previous in enumerate(reversed(recent[-8:]), 1):
            if previous not in CONDITIONS:
                continue
            middle = recent[-distance + 1:] if distance > 1 else ()
            subject = recent[-1]
            subject_scale = 1.0 if subject in {'you', 'it'} else 0.45
            if subject in {'they', 'he', 'she', 'this', 'there', 'someone', 'we'}:
                subject_scale = 0.8
            if subject == 'i':
                subject_scale = 0.6
            strength = CONDITIONS[previous] * 0.7 ** max(0, distance - 2)
            if any(w in PREDICATES for w in middle):
                strength *= 0.15
            if word == 'be' and previous != 'whether':
                strength *= 0.1
            value += strength * subject_scale * PREDICATES[word]
            break

    if recent and recent[-1] in CONDITIONS and word in {
        'it', 'you', 'we', 'they', 'he', 'she', 'there',
    }:
        strength = 0.3 if word == 'it' else 0.05
        if recent[-1] == 'whether':
            strength = 1.2 if word == 'it' else 0.35
        value += strength

    if word in PAIR_TERMS:
        for distance, previous in enumerate(reversed(recent[-16:]), 1):
            if previous == 'them':
                break
            if previous != 'between':
                continue
            middle = recent[-distance + 1:] if distance > 1 else ()
            if word == 'and' or distance <= 3:
                strength = PAIR_TERMS[word] * 0.91 ** max(0, distance - 2)
                if 'and' in middle or ('two' in middle and word != 'different'):
                    strength *= 0.2
                if any(',' in w for w in middle):
                    strength *= 0.35
                if word == 'two' and recent[-1] in {'first', 'last', 'next'}:
                    strength *= 0.45
                if word == 'and' and not token.startswith(' '):
                    strength *= 0.2
                value += strength * (0.5 if raw[:1].isupper() else 1.0)
            break
    if word in {'others', 'them', 'us', 'other', 'these'} and 'among' in recent[-3:]:
        value += 1.0
    if word in {'to', 'with'}:
        for distance, previous in enumerate(reversed(recent[-3:]), 1):
            strength = relation_strength(previous, word)
            if strength:
                if distance > 1:
                    strength *= 1.15 if recent[-1] in {'it', 'them'} else 0.6
                value += strength
                break

    if continuation:
        value = 0.0
        recent = recent[:-1] + (recent[-1] + word,)
    else:
        if raw in {'.', '!', '?', ';'} and not (recent and recent[-1].isdigit()):
            recent = ()
        recent = (recent + (word,))[-24:]
    return (doc, recent), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:4932 -- a "relation frame" detector.

What it does: this component is nearly silent on most text, but it switches on in two
kinds of phrase, both about a pairing or a choice between two things:

1. Pair frames. After a relation word such as "between", "among", "both", "versus",
   "difference", or a stem like connect / relat / link / compar, the component fires on
   the word that completes the pair: strongest on "them" and "two" ("between them",
   "between the two"), weaker on "to", "with", "from". It also fires on the "and" that
   closes the pair ("between A and B"). Articles in between ("between the two") do not
   count as a step, and the frame closes at "and" / "or" or after 8 words.

2. Conditional frames. The verb right after "whether / if / unless" plus a pronoun
   ("whether it is", "if you are", "if there were") fires; the pronoun itself does not.

Otherwise the program predicts 0. The values are least-squares weights on 1024 training
rows, rounded; they are in activation units, so the prediction matches the component's
scale.

Why: this is the part of the component's activation that a short rule can capture. Its
variance is mostly diffuse, small values that no word-level rule reproduces. Predicting
0 leaves that part out, which is why the e2e effect of the program is close to switching
the component off.
"""

READS = ()

# Words that open a pair or relation frame, and stems that do the same.
OPENERS = {
    "between", "among", "amongst", "both", "versus", "vs", "difference", "differences", "entre",
}
OPENER_STEMS = ("connect", "relat", "link", "compar", "correlat", "interact")
# Words that complete the pair right after the opener.
COMPLETERS = {"them", "two", "both", "other", "others", "each"}
PREPOSITIONS = {"to", "with", "from", "via", "by"}
# Articles and determiners that may sit between the opener and its completer.
ARTICLES = {
    "the", "a", "an", "all", "any", "these", "those",
    "its", "their", "his", "her", "my", "our", "your",
}
# Conditional frame: "whether / if / unless" + pronoun, then the verb.
COND_WORDS = {"whether", "if", "unless"}
PRONOUNS = {"it", "you", "they", "we", "there", "he", "she", "i", "this", "that"}
BE_VERBS = {"is", "are", "was", "were", "'re", "’re", "'s", "’s", "have", "had", "be"}
SPAN = 8


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if carry is None or (
        len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]
    ):
        carry = (None, None, None)
    # since: words since the last opener (0 = right after it), or None if no open frame.
    since, prev, prev2 = carry
    value = 0.0
    if since == 0:
        if word in COMPLETERS:
            value = 1.8
        elif word in PREPOSITIONS:
            value = 0.6
    elif since is not None and word == "and":
        value = 0.5  # the "and" closing "between A and B"
    if prev2 in COND_WORDS and prev in PRONOUNS:
        value = max(value, 0.7 if word in BE_VERBS else 0.2)

    # Update the frame state with the current word.
    if word in OPENERS or word.startswith(OPENER_STEMS):
        since = 0
    elif since is not None:
        if word in ("and", "or") or since >= SPAN:
            since = None
        elif word not in ARTICLES:
            since += 1
    return (since, word, prev), value

programs.luna:
"""A small phrase-level estimate: a subject plus auxiliary, a participial
relation followed by 'to'/'with', or 'two' in a nearby 'between' phrase."""
READS = ()

AUXILIARIES = frozenset({
    "am", "is", "are", "was", "were", "be", "been", "being",
    "'m", "'s", "'re", "have", "has", "had", "'ve", "do", "does",
    "did", "will", "would", "can", "could", "should", "may", "might",
})
SUBJECTS = frozenset({
    "i", "you", "he", "she", "it", "we", "they", "there", "this", "that",
    "who", "what", "which",
})


def step(carry, prefix, upstream):
    position = prefix.position
    word = prefix.token_strings[-1].strip().casefold()
    has_previous = position > 0
    same_document = (
        has_previous
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = (
        prefix.token_strings[-2].strip().casefold() if same_document else ""
    )

    if word == "two" and same_document:
        recent = [
            item.strip().casefold()
            for item in prefix.token_strings[max(0, position - 3):position]
        ]
        if "between" in recent:
            return None, 0.44

    if previous in SUBJECTS and word in AUXILIARIES:
        return None, 0.112

    if word in {"to", "with"} and previous.endswith(("ed", "ing")):
        return None, 0.112

    return None, 0.0

programs.sol:
"""Approximate a detector of Slavic preposition-like word fragments.

Short word beginnings such as po-, pod-, od-, na-, v-, w- and z- receive
positive values. Recent Slavic letters and function words, relative to
recent alphabetic text, keep these responses from firing on English
lookalikes. Longer fragments weaken the response. Cyrillic counterparts
are weaker, with a boost from Ukrainian spelling. Common internal endings
and acute-vowel fragments get smaller signed responses. The phrase
'instance of' is handled separately. All context resets at document breaks.
"""
READS = ()

# Prepositions, productive prefixes, and their short onset fragments.
LATIN_PREFIXES = (
    (2.5, ('pod', 'pok', 'zap', 'od', 'po')),
    (2.3, ('ob', 'spo')),
    (1.9, ('na', 'do', 'pri', 'przy', 'wy', 'roz')),
    (1.75, ('př', 'prz', 'pro', 'za', 'vy', 'zm', 'zn', 'z')),
    (1.55, ('nad', 'pred', 'przed', 'u', 'sk')),
    (1.7, ('o',)),
    (1.4, ('ok', 'os', 'og')),
    (1.3, ('v', 'ú', 'naj', 'nep', 'dla')),
    (1.15, ('ne', 'pre', 'pr', 'sp', 'w', 'ro', 'ze')),
    (0.7, ('n', 'p', 's', 've', 'st')),
    (0.4, ('k',)),
)
CYRILLIC_PREFIXES = (
    (0.78, ('зап', 'заб')),
    (0.62, ('в', 'у', 'з')),
    (0.52, ('по', 'при', 'про', 'до', 'од')),
    (0.44, ('об', 'нап')),
    (0.34, ('на', 'под', 'о', 'п', 'пр')),
    (0.25, ('за', 'из', 'от', 'для')),
)
WEST_LETTERS = set('ěřůąćęłńśźżľĺŕďťňý')
SHARED_LETTERS = set('šžč')
LANGUAGE_WORDS = {
    'jest', 'jsou', 'není', 'jako', 'který', 'které', 'která',
    'się', 'nie', 'že', 'sú', 'sme', 'swoje', 'oraz',
}
# Slavic noun/adjective endings and the instrumental ending -ou.
ENDINGS = {
    'ost', 'osti', 'nost', 'nosti', 'ov', 'ow', 'ovo', 'owo', 'owe', 'ou',
}
INTERNAL_PREFIXES = ('pod', 'po', 'od', 'ob', 'roz', 'za', 'vy', 'zn', 'oz')


def prefix_response(word, groups):
    # Prefer the longest matching fragment over its shorter ancestor.
    best = ''
    level = 0.0
    for strength, roots in groups:
        for root in roots:
            if word.startswith(root) and len(root) > len(best):
                best, level = root, strength
    if best:
        level *= 0.68 ** max(0, len(word) - len(best))
    return level


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        language = ukrainian = letters = 0.0
        previous = ''
    else:
        _, language, ukrainian, letters, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    language *= 0.975
    letters = 0.975 * letters + sum(c.isalpha() for c in word)
    ukrainian *= 0.97
    language += sum(0.7 for c in word if c in WEST_LETTERS)
    language += sum(0.3 for c in word if c in SHARED_LETTERS)
    if word in LANGUAGE_WORDS or word.startswith(('př', 'prz')):
        language += 0.8
    ukrainian += sum(0.5 for c in word if c in 'іїєґ')
    language = min(language, 4.0)
    ukrainian = min(ukrainian, 2.0)
    slavic = min(1.0, language / max(0.8, 0.018 * letters))
    uk = min(1.0, ukrainian)
    boundary = (
        token.startswith(' ') or not previous or not previous[-1:].isalpha()
    )
    value = 0.0
    if word.isalpha():
        if any('\u0400' <= c <= '\u04ff' for c in word):
            if boundary:
                value = next((level for level, words in CYRILLIC_PREFIXES
                              if word in words), 0.0)
                if token.strip()[:1].isupper() and word in {'в', 'п', 'о'}:
                    value *= 0.82
                value *= 1.0 + 0.8 * uk
            elif word in {'в', 'у', 'о', 'об', 'од', 'оз'}:
                value = 0.12 * (1.0 + uk)
            if word == 'з' and boundary:
                value = (
                    0.55 if token.strip().isupper() else 0.30
                ) + 0.8 * uk
            if word == 'а' and boundary:
                value = -0.14 * (1.0 + uk)
        elif boundary:
            value = prefix_response(word, LATIN_PREFIXES) * slavic
            if word in {'of', 'on'}:
                value = 0.0
            if len(word) == 1 and token.strip().isupper():
                value *= 0.6
            if word in {'a', 'ale'}:
                value = -0.72 * slavic
            elif word in {'to', 'co', 'by', 'aby'}:
                value = -0.35 * slavic
            elif word in {'jest', 'js', 'je', 'jako', 'jed'}:
                value = 0.8 * slavic
        else:
            if word in ENDINGS:
                value = 0.78 * slavic
            elif word.startswith(INTERNAL_PREFIXES):
                value = 0.48 * prefix_response(word, LATIN_PREFIXES) * slavic
            elif word in {'v', 'z', 'u', 'na'}:
                value = 0.45 * slavic
            elif (len(word) <= 2 and word[0] in 'áéí') or word in {
                'ę', 'ć', 'ích', 'ýt',
            }:
                value = (-0.35 if len(word) == 1 else -0.9) * slavic
            elif word in {'č', 'š', 'ř', 'ů', 'ý', 'ú', 'ých'}:
                value = 0.28 * slavic
            elif word == 'ed' and previous.strip().lower() in {'př', 'pr'}:
                value = 1.3 * slavic
    if word == 'instance':
        value = 0.16 if previous.strip().lower() == 'for' else 0.60
    elif word == 'of' and previous.strip().lower() == 'instance':
        value = 0.53
    return (doc, language, ukrainian, letters, token), float(value)

"""Approximate an English question/exercise-introduction signal.

Recognize selected question words, task verbs, 'the following', and problem
setup words. Capitalization, clause/line openings, and recent quantities
or mathematics strengthen these cues. Explicit user-message beginnings
are stronger than assistant discussion. A few grammatical continuations
have their own responses. Other tokens stay near zero: this deliberately
omits the component's many smaller, idiosyncratic lexical responses.
"""
from collections import deque
import re

READS = ()
# Embedded form, capitalized form, and sensitivity to clause openings.
QUESTIONS = {
    'what': (0.49, 0.79, 0.3),
    'how': (-0.03, 0.32, 0.35),
    'why': (0.09, 0.32, 0.34),
    'which': (-0.09, 0.47, 0.1),
    'who': (-0.08, 0.18, 0.13),
}
# Ordinary use versus a capitalized instruction.
TASKS = {
    'find': (0.1, 0.45), 'write': (0.01, 0.31),
    'explain': (0.05, 0.58), 'determine': (0.13, 0.45),
    'calculate': (-0.02, 0.25), 'give': (0.02, 0.38),
    'describe': (-0.01, 0.6), 'draw': (0.03, 0.28),
    'solve': (-0.07, 0.31), 'simplify': (0.07, 0.68),
    'use': (-0.05, 0.09), 'show': (-0.1, 0.14),
    'evaluate': (0.01, 0.38), 'state': (-0.06, 0.09),
    'identify': (0.15, 0.50), 'convert': (-0.05, 0.40),
    'compute': (-0.06, 0.25), 'complete': (0.00, 0.20),
    'express': (0.00, 0.20),
}
CONDITIONS = {
    'given': 0.12, 'assuming': 0.15, 'suppose': 0.17,
    'consider': 0.22, 'assume': 0.30,
}
MATH_TASKS = {'round': 0.52, 'list': 0.27, 'factor': 0.14, 'expand': 0.35}
PLURAL_COUNTS = frozenset('two three four five six seven eight nine ten'.split())
MATH_WORDS = frozenset('''math mathematics maths algebra physics geometry
calculus equation function functions formula mass velocity acceleration
speed radius triangle cylinder probability distance derivative integral
volume voltage resistance molar heat gradient fraction solve calculate
find simplify compute'''.split())

CUES = (set(QUESTIONS) | set(TASKS) | set(CONDITIONS) | set(MATH_TASKS)
        | PLURAL_COUNTS | {'following', 'if', 'a', 'an', 'let'})


def cue_value(word, capital, token, previous, history):
    """Combine lexical strength with a short, readable local context."""
    recent = list(history)
    numbers = min(sum(x[0] for x in recent[-30:]) / 5, 1.0)
    mathematics = min(sum(x[1] for x in recent) / 2, 1.0)
    boundary = not previous.rstrip()[-1:].isalpha()
    line_start = '\n' in previous
    clause_start = line_start or not previous or previous.rstrip().endswith(
        (',', ':', ';', '.', '?', ')'))
    value = -0.002
    if word in QUESTIONS:
        low, high, opening = QUESTIONS[word]
        value = (high if capital else low) + opening * boundary
        boost = 0.25 if word == 'what' else 0.15 if word == 'how' else 0.06
        value += boost * (numbers + mathematics)
    elif word in TASKS:
        value = TASKS[word][capital] + 0.30 * (capital and clause_start)
        value += 0.12 * numbers + 0.18 * mathematics
        if word in ('find', 'write'):
            value += 0.15 * line_start
    elif word == 'following':
        value = 0.12 + 0.92 * (previous.strip().lower() == 'the')
        value += 0.15 * numbers + 0.12 * mathematics
    elif word == 'if':
        value = (0.10 if capital else -0.03)
        value += 0.09 * numbers + 0.15 * mathematics
        value += 0.08 * (capital and line_start)
    elif word in CONDITIONS and capital:
        value = CONDITIONS[word] + 0.20 * numbers + 0.15 * mathematics
    elif word in MATH_TASKS and capital:
        value = MATH_TASKS[word] * (0.30 + 0.70 * numbers)
        value += 0.10 * mathematics
    elif word == 'let' and capital:
        value = 0.02 + 0.14 * numbers + 0.15 * mathematics
    elif word in PLURAL_COUNTS and capital:
        value = 0.12 + 0.07 * numbers + 0.15 * mathematics
        value += 0.12 * line_start
    elif word in ('a', 'an') and capital:
        value = 0.06 + 0.15 * line_start
        value += 0.09 * numbers + 0.12 * mathematics
        if not previous:
            value = 0.80
    elif word in ('a', 'an') and not previous:
        value = 0.16 if token[:1].isspace() else 0.70
    if word in QUESTIONS or word in TASKS or word == 'following':
        value += 0.20 * max(0.0, 1 - len(history) / 30)
    return value


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, history, role, message_age = '', deque(maxlen=60), '', 999
    else:
        _, previous, history, role, message_age = carry
    if previous == '<|im_start|>':
        role, message_age = token.strip(), 0
    elif token == '<|im_end|>':
        role, message_age = '', 999
    else:
        message_age += 1

    # Recognize a word completed by this token and the preceding fragment.
    word = token.strip().strip('"\'“”/.:')
    if word.isalpha() and token[:1].isalpha() and previous:
        tail = re.search(r'[A-Za-z]+$', previous)
        if tail:
            word = tail[0] + word
    capital, word = word[:1].isupper(), word.lower()
    value = cue_value(word, capital, token, previous, history) if word in CUES else -0.002

    if role == 'assistant':
        if word == 'let' and capital:
            value = -0.04
        elif word in TASKS or word in CONDITIONS:
            value *= 0.5
        elif word in QUESTIONS:
            value -= 0.12
        elif word in ('a', 'an') and capital:
            value = 0.0
    elif role == 'user' and (word in TASKS or word in QUESTIONS or word == 'following'):
        value += 0.25 * max(0.0, 1 - message_age / 30)

    # Short grammatical continuations: 'which of', 'Find the', 'How do'.
    prior = previous.strip().lower()
    if word == 'of' and prior == 'which':
        value = 0.59 if previous.strip()[:1].isupper() else 0.41
    elif prior in TASKS and previous.strip()[:1].isupper():
        if word == 'the':
            value = 0.40
        elif word in ('a', 'an'):
            value = 0.18
    elif prior in ('what', 'how') and word in ('is', 'are', 'do', 'does', 'did'):
        value = -0.07 if prior == 'what' else -0.18
    history.append((bool(re.search('[0-9]', token)), word in MATH_WORDS))
    return (doc, token, history, role, message_age), float(value)

"""Lexical specificity / indefinite-quantity / certainty cues, strongest on 'certain'.

This detects wording, not whether a proposition really is certain. It includes
related word roots and translations. Responses are smaller in the idioms 'make
sure' and 'in particular'. Only the current and previous tokens are needed.
Other tokens are zero; small, unrelated token-specific responses are omitted.
"""
READS = ()

# Translations of 'some', 'certain', or 'specific', grouped by response strength.
TRANSLATIONS = {
    5.7: {'某些'},
    4.3: {'certains'},
    3.4: {'certo'},
    2.4: {'特定', 'bestimm'},
    2.1: {'某种', 'некоторых'},
    1.8: {'某', '某个', '一定', '一定的', '有些', '不确定', '특정'},
    1.4: {'某某', 'некотор', 'некоторые', 'alguns', 'algumas', 'alcuni'},
    1.1: {'algunos', 'algunas', 'بعض', '有一些', '的一些', '了一些'},
    0.9: {'一些'},
    0.75: {'各种', '有的', '确定', 'конкрет', 'einige', '肯定'},
}


def response(token, previous):
    text = token.strip()
    word, before = text.lower(), previous.strip().lower()
    spaced, capital = token.startswith(' '), text[:1].isupper()
    if word == 'certain':
        if before in {'is', 'was', 'make', 'une', 'not', 'almost'}:
            return 7.6
        return (8.1 if capital else 8.5) if spaced else 7.4
    if word in {'certainly', 'certainty'}:
        return 3.2 if not spaced and capital else 2.9
    if word == 'uncertain':
        return 2.45
    if word in {'uncertainty', 'uncertainties'}:
        return 1.0
    # The same lexical root can be split or used as a code identifier.
    if word.lstrip('-_') == 'cert':
        if word.startswith(('-', '_')):
            return 1.9
        return 3.4 if spaced else (2.9 if capital else 1.7)
    if word == 'certs':
        return 2.4
    if word.startswith('certificat') or word == 'certified':
        return 1.1 if spaced or capital else 0.7
    if word == 'certify':
        return 1.55
    if word == 'ertain':
        if before.endswith('c'):
            return 3.9 if before.endswith(('unc', 'inc', 'asc', 'ac')) else 7.1
        return 2.5
    if word in {'erto', 'erta', 'ertos', 'ertas'}:
        if before in {'c', 'ci'}:
            return 2.8
    if before in {'certain', 'cert'} and word in {'e', 'es', 's', 'ainty'}:
        return 1.5
    if word == 'some':
        if spaced:
            return 1.0 if capital else 1.27
        return 1.14 if capital else 0.91
    if word in {'several', 'various'}:
        value = 0.91 if word == 'several' else 1.39
        return value * 0.8 if capital else value
    if word == 'sure':
        if before in {'make', 'makes', 'making', 'made'}:
            return 0.9
        return 1.65 if spaced else (1.45 if capital else 0.95)
    if word == 'unsure':
        return 1.3
    if word == 'particular':
        if before == 'in':
            return 1.12 if previous.strip().istitle() else 1.48
        return 2.1 if before in {'this', 'that', 'any'} else 1.8
    if word in {'particularly', 'particul', 'confident', 'definitely', 'doubtful'}:
        return 0.8
    if word.lstrip('-') == 'specific':
        if word.startswith('-') or capital:
            return 0.75
        return 1.03 if spaced else 0.6
    if word in {'confidence', 'doubt', 'specifically', 'specificity'}:
        return 0.35
    if word in {'somewhat', 'sometimes', 'somewhere', 'somehow'}:
        return 0.23
    for value, words in TRANSLATIONS.items():
        if word in words:
            return value
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), response(token, previous)

"""Estimate a response to unaccented Vietnamese-shaped syllables.

The main term uses vowel clusters, consonant endings, and whether a token
completes a syllable after an onset like th-, nh-, or tr-. A decaying count of
Vietnamese words and distinctive letters modulates it. Small spelling and
formatting baselines cover background means, not individual token identities.
Chat and reasoning boundaries have separate fixed responses. The program
captures these tendencies, not most of the component's variance.
"""
import re
import unicodedata

READS = ()
VIETNAMESE_LETTERS = re.compile(
    '[ăđơưạảấầẩẫậắằẳẵặẹẻẽếềểễệỉịọỏốồổỗộớờởỡợụủứừửữựỳỵỷỹ]', re.I
)
SYLLABLE = re.compile(
    '(ngh|ch|gh|gi|kh|ng|nh|ph|qu|th|tr|[bcdghklmnprstvx])?'
    '(a|ai|ao|au|ay|e|eo|eu|i|ia|ie|ieu|iu|o|oa|oai|oay|oe|oi|oo|'
    'u|ua|uai|uay|ue|ui|uo|uoi|uou|uy|uya|uye|uyu|uu|y|ye|yeu)'
    '(ng|nh|ch|[cmnpt])?$'
)
MARKED_ONSETS = {'ch', 'kh', 'ng', 'nh', 'qu', 'th', 'tr'}
DISTINCTIVE_WORDS = set("""
khong duoc nguoi nhung nhieu phai chuyen thuoc thuc hien trong truoc
thanh nguyen tieng viet nhap xuat ngay cung hoac nghia nhan nghiem
duong truong thong nhat nghe phuong cach quyen
""".split())
COMMON_WORDS = set("""
cua cau neu dieu kien lenh sach dung dau them tinh ham cac giai la va
co so bo do da di den cho con ban toi mot nam may qua ta hai khi thi
nhu ma ve ra vi rat
""".split())


def word_evidence(word):
    word = word.lower()
    if word in DISTINCTIVE_WORDS:
        return 1.0
    if word in COMMON_WORDS:
        return .2
    return 0.0


def background(token):
    word = token.strip()
    value = -.0013 + .0018 * token[:1].isspace()
    if not word:
        return value + .0033
    if word.isalpha():
        if len(word) == 2:
            value -= .0036
        elif len(word) == 7:
            value += .0028
        elif len(word) >= 8:
            value += .0043
        if word.isupper():
            value -= .0033
        if not word.isascii() and any(
            'LATIN' in unicodedata.name(c, '') for c in word
        ):
            value -= .0067
    if word.isascii() and all(not c.isalnum() for c in word):
        if any(c in '+*=<>!&|' for c in word):
            value += .0054
        if any(c in '()[]{}' for c in word):
            value += .0032
    if len(word) > 1 and word[0] in '._/':
        value += .0035
    return value

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, previous_word, evidence = carry
    token = prefix.token_strings[-1]
    evidence = .96 * evidence + bool(VIETNAMESE_LETTERS.search(token))
    continuing = token.isascii() and token.isalpha()
    if continuing:
        word = (previous_word + token)[-30:]
    else:
        evidence += word_evidence(previous_word)
        end = re.search('[a-zA-Z]+$', token)
        word = end[0] if end else ''
    language = min((evidence + word_evidence(word)) / 3, 1.0)
    continuing = continuing and bool(previous_word)
    value = background(token)
    stripped = token.strip().lower()
    match = SYLLABLE.fullmatch(stripped) if stripped.isascii() else None
    if match:
        onset, vowel, coda = match.groups()
        vowel_cluster = len(vowel) > 1
        palatal_ending = coda in ('nh', 'ch')
        velar_ending = coda in ('ng', 'c')
        other_ending = coda in ('m', 'n', 'p', 't')
        value += (-.0037 + .0506 * language) * vowel_cluster
        value += (.0153 + .1573 * language) * palatal_ending
        value += (-.0051 + .0894 * language) * velar_ending
        value += .0726 * language * other_ending
        if continuing:
            if not onset:
                value += .0235 * vowel_cluster
                value += .0125 * palatal_ending + .0069 * velar_ending
            joined = SYLLABLE.fullmatch(word.lower())
            if joined and joined[1] in MARKED_ONSETS:
                value += .0435 + .0738 * language
    if token in ('<think>', '</think>'):
        value = .087
    elif token == '<|im_start|>':
        value = .0355
    elif token == '<|im_end|>':
        value = -.0241
    elif token == '<|endoftext|>':
        value = -.0195
    return (doc, word, evidence), float(value)

