programs.haiku:
"""layers.0.mlp.down_proj:4939 -- a "size / quantity / direction modifier" word detector.

What the component does: it fires on a small set of words that work as modifiers before a
noun, mainly the Chinese one-character adjectives 大 (big), 小 (small), 老 (old), 新 (new),
早 (early), 好 (good), 快 (fast), 全 (whole), and then 高 (high), 少 (few), 长 (long), 左/右
(left/right), 黑 (black), and numbers and determiners such as 三 (three), 这 (this), 各 (each).
English has the same kind of words: other, either, various, high, full, right, left, big,
one. It is almost silent on everything else (punctuation, function words, most nouns and
verbs). Its activation is set by the current token, with little dependence on context.

This program predicts that: a fixed lexicon, graded by how strongly each word fires. The
grades (about 3.2 for 大/小/老/新 down to about 0.45 for weaker adjectives) come from running
the model on each vocabulary item. Tokens that fuse a particle or numeral with a modifier
(的大, 一小, 三大) get the modifier's grade, lowered a little.
"""

import unicodedata

READS = ()

# Chinese one-character modifiers (adjectives, numbers, directions, determiners), by strength.
CLASSES = [
    (3.2, "大小老新"),                              # big, small, old, new
    (2.5, "早好快全"),                              # early, good, fast, whole
    (1.8, "少高长黑左右北晚强硬深太"),               # few, high, long, black, left, right, north, late, strong, hard, deep, too
    (1.2, "多短慢贵满白软三八难真远窄冷西两"),        # many, short, slow, expensive, full, white, soft, three, eight, hard, real, far, narrow, cold, west, two
    (0.8, "黄近红猛轻弱细低紫矮幼青重美乱蓝易厚正薄净暗瞎狠四五六七九十东南下"),
    (0.8, "一"),                                    # one
    (0.45, "暖急甜胖明粗坏紧傻宽绿直饱干旧斜稀瘦清浅空咸闲纯嫩热平穷亮柔富脏假灰中上前后外内这有不无每几双"),
]
# Traditional forms of the same characters.
TRAD = {"滿": "满", "總": "总", "兩": "两", "廣": "广", "東": "东", "貴": "贵", "軟": "软", "強": "强",
        "難": "难", "長": "长", "細": "细", "輕": "轻", "黃": "黄", "紅": "红"}

CHINESE = {}
for value, chars in CLASSES:
    for ch in chars:
        CHINESE.setdefault(ch, value)
for trad, simp in TRAD.items():
    CHINESE.setdefault(trad, CHINESE.get(simp, 0.0))

# English words that behave the same way ("other dogs", "high value", "one of").
ENGLISH = {"other": 0.8, "either": 0.9, "neither": 0.75, "various": 0.9, "full": 0.9, "high": 0.9,
           "right": 0.7, "left": 0.6, "big": 0.75, "little": 0.5, "black": 0.6, "one": 0.35}


def value(token):
    """The predicted activation of one token, by lexicon lookup."""
    token = unicodedata.normalize("NFKC", token)  # Kangxi radical forms, e.g. ⼤ -> 大
    word = token.strip().lower()
    if word in ENGLISH:
        return ENGLISH[word]
    if len(token) == 1:
        return CHINESE.get(token, 0.0)
    # 的大, 的小: the modifier after the particle 的 comes out as one token
    if token[0] == "的" and len(token) == 2:
        return CHINESE.get(token[1], 0.0)
    # 一大, 三大, 各大: a number or determiner fused with 大, 小, 老 or 新
    if 2 <= len(token) <= 3 and token[-1] in "大小老新" and token[0] in "一两三四五六七八九各每人":
        return 0.8 * CHINESE.get(token[-1], 0.0)
    return 0.0


def step(carry, prefix, upstream):
    """The activation at this position: the lexicon grade of the current token. It needs no
    state from earlier positions, so the carry is unused."""
    return carry, float(value(prefix.token_strings[-1]))


if __name__ == "__main__":
    for word in ["大", "小", "新", "高", "other", "的大", "一小", "的"]:
        print(repr(word), value(word))

