"""Approximate Markdown boundary signal. Spaced bold markers are positive,
especially after list markers. Bare bold markers are positive at line openings
and weakly negative elsewhere. Multi-hash headings are usually negative;
sentence endings soften levels three and four. Code fences are mildly positive.
Other tokens get a tiny baseline. Context resets at each document boundary.
"""
import re

READS = ()
LIST_LABEL = re.compile(r'\s*(?:#{1,6}\s*)?(?:>\s*)?([-+*]|\d+[.)])\s*')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    line = before.rsplit('\n', 1)[-1]
    sentence = before.rstrip().endswith(('.', '!', '?'))
    value = 0.001
    if token == ' **':
        item = LIST_LABEL.fullmatch(line)
        value = 0.34
        if item:
            value = 0.9 if item[1] == '*' else 1.5
            if '#' in line:
                value = 2.0
    elif token == '**':
        if before.endswith('\n\n'):
            value = 0.73
        elif not line.strip():
            value = 0.23
        else:
            value = -0.025
    elif token in ('**:', ':**'):
        value = -0.09
    elif token.strip() and set(token.strip()) == {'#'}:
        level = len(token.strip())
        if level == 2:
            value = -0.15
        elif level == 3:
            value = -0.35 if sentence else -0.67
        elif level == 4:
            value = -0.15 if sentence else -0.5
        elif level in (5, 6):
            value = -0.55
        if token.startswith(' ') and level in (2, 3):
            value = -0.06 if level == 2 else -0.45
        if not before:
            value = 0.2 if level == 3 else 0.0
    elif token.strip() == '```':
        value = 0.22 if sentence else 0.07
    after = (before + token.replace('\\n', '\n'))[-200:]
    return (doc, after), float(value)

