    mark = token.lstrip()

    hashes = len(mark) - len(mark.lstrip("#"))
    if 2 <= hashes <= 8 and line_start:
        if len(mark) == hashes or mark[hashes:hashes + 1].isspace():
            prediction = -0.20 if hashes <= 3 else -0.46

