    if mark.startswith("**") and not mark.startswith("***"):
        if token.startswith(" "):
            prediction = 0.26
        elif not before or before[-1:].isspace():
            prediction = 0.48

    if "```" in token and line_start:
        prediction = 0.27

    suffix = (before + token)[-96:]
    return (doc, suffix), float(prediction)

