The strongest cues are market and economy words; lighter cues include industry,
population, society, and military vocabulary. Word pieces are joined only while
they continue the same word, so spellings split across tokens still match.
"""

READS = ()


def _cue(word):
    if not word:
        return 0.0

    if "market" in word:
        if "marketplace" in word:
            return -1.8
        if "marketing" in word:
            return -0.2
        if "marketed" in word:
