    if "mercado" in word or "marché" in word or "рын" in word:
        return -1.9

    if "econom" in word:
        if word.endswith(("economy", "economies")):
            return -2.8 if word.endswith("economy") else -1.5
        if "economical" in word:
            return -1.1
        if "economically" in word:
            return -1.0
        if "economist" in word:
            return -0.7
        if "economics" in word:
            return -0.5
        return -1.4
    if "经济" in word or "經濟" in word:
        return -1.2
    if "industr" in word:
        if word.endswith("industry"):
            return -1.25
        if word.endswith("industries"):
            return -0.66
        if word.endswith("industrial"):
            return -0.05
        return -0.8
    if "行业" in word or "業界" in word:
        return -0.85

    if "populat" in word:
        return -0.78
    if "societ" in word:
        if "societal" in word:
            return -1.55
        if "societies" in word:
            return -0.58
        return -0.95
    if "社会" in word or "社會" in word:
        return -1.55
    if "militar" in word:
        return -0.56
    if "domestic" in word:
        return -0.63
    if "workforce" in word:
        return -0.76
    if "demand" in word:
        if word.endswith("demand"):
            return -0.4
        if word.endswith("demands"):
            return -0.16
        return -0.1
    if "parliament" in word or "congress" in word:
        return -0.52
    if "government" in word:
        return -0.23
    if "social" in word:
        return -0.22
    if "community" in word:
        return -0.17
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = ""
    if carry is not None and carry[0] == document:
        previous = carry[1]

    text = token.lower()
    if text and text[0].isalpha():
        text = previous + text

    words = []
    run = ""
    for character in text:
        if character.isalpha():
            run += character
        else:
            if run:
                words.append(run)
                run = ""
    if run:
        words.append(run)

    if token and token[-1].isalpha():
        tail = words[-1] if words else ""
    else:
        tail = ""
    value = min((_cue(word) for word in words), default=0.0)
    # A conservative shrinkage matches the weaker, less consistent cue response.
    return (document, tail), float(0.65 * value)

