"""Detect 'at' word forms, with strong suppression in 'look at' phrases.

Space-prefixed 'at' and capitalized 'At' give large positive predictions.
Forms of 'look' nearly cancel the lowercase signal; 'arrive' and 'aim'
reduce it. Bare lowercase 'at' is weaker inside a word than at a boundary.
Tab-prefixed, punctuation-prefixed, uppercase and identifier-suffix forms
have separate strengths. All other tokens predict zero. State tracks only
the trailing word and character, and resets for each document.
"""
import re

READS = ()
LOOKING = {'look', 'looks', 'looked', 'looking'}
ARRIVING_OR_AIMING = {
    'arrive', 'arrives', 'arrived', 'arriving',
    'aim', 'aims', 'aimed', 'aiming',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = ''
        last_char = ''
        first = True
    else:
        previous = carry[1]
        last_char = carry[2]
        first = False
    previous = previous.lower()
    token = prefix.token_strings[-1]
    value = 0.0
    if token == ' at':
        value = 2.52 if first else 1.82
        if previous in LOOKING:
            value = 0.23 if previous in {'looking', 'looked'} else 0.08
        elif previous in ARRIVING_OR_AIMING:
            value = 1.03
    elif token in ('At', ' At'):
        value = 1.90
    elif token == 'at':
        value = 0.26 if last_char.isalpha() else 1.35
        if last_char.isspace():
            value = 1.60
    elif token == ' AT':
        value = 0.99
    elif token == '\tat':
        value = 2.57
    elif len(token) > 2 and token.lstrip('._-/—(\"\'“‘').lower() == 'at':
        value = 1.50
    elif token.endswith('At') and len(token) > 2:
        value = 0.90

    # Retain only the trailing word, joining pieces split across tokens.
    text = (previous + token)[-40:]
    match = re.search(r'([A-Za-z]+)$', text)
    word = match.group(1) if match else ''
    return (doc, word, token[-1:] or last_char), float(value)

