"""Detects the English preposition "at", in whatever spelling the tokenizer gives it.

What it does: the component is close to a pure "at" detector. On the word " at" it reads
about 1.8; on "At" at the start of a sentence or line about 1.9; on "at" glued to a
bracket or underscore about 1.3; on "at" inside a longer word (inf|at|uation) about 0.3;
on the all-capitals "AT" about 0. Everywhere else it is near 0.

One context matters: after a verb of looking ("look at", "looking at", "stared at"),
"at" is a different sense and the component drops to about 0.15. The word after " at"
(especially "the", "least") is nudged slightly negative.
"""

READS = ()

LOOK_WORDS = {"look", "looks", "looked", "looking", "glance", "glanced", "stare", "stared",
              "staring", "peek", "gaze", "gazed", "gazing", "glimpse", "peeked", "peeking"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    core = "".join(c for c in tok if c.isalpha())
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""
    else:
        prev = prefix.token_strings[-2]
    if core.lower() != "at":
        # the word right after a standalone " at" is nudged negative
        return carry, -0.1 if prev == " at" else 0.0
    if tok == " AT":
        value = 1.0
    elif core == "AT":
        value = 0.0
    elif tok == " at":
        value = 1.8
    elif core == "At":
        value = 1.85
    elif prev[-1:].isalpha():
        value = 0.3  # "at" inside a word, e.g. inf|at|uation
    else:
        value = 1.3
    if prev.strip().lower() in LOOK_WORDS:
        value = 0.15
    return carry, value

