"""A negative pulse at opening quotes, especially after an attribution of speech.

Quote shape, leading space, and the immediate lead-in set the pulse size.
A reporting verb in the last twelve tokens strengthens it, with recency decay.
Weak rules also cover code fences and quoted HTML attribute values.
Closing quotes, in-word apostrophes, and ordinary text are mostly ignored.
"""
READS = ()

REPORTING = set('''
says said saying told replied writes wrote stated declared announced
exclaimed whispered shouted
'''.split())
MENTIONING = set('''
say tell tells ask asks asked reply replies explain explains explained state
states report reports reported note notes noted remark remarked observe
observed claim claimed conclude concluded respond responded answer answered
read reads mention mentions mentioned quote quotes quoting
'''.split())
NAMING = set('as called termed entitled titled dubbed meaning'.split())
TERMS = set('like named name term phrase word words means'.split())
COPULAS = set('be is are was were been being become becomes became'.split())
CHINESE_SPEECH = (
    '说', '說', '说道', '說道', '问', '問', '表示', '声称', '聲稱'
)
LEFT_QUOTES = {
    '“': -0.60, '‘': -0.14, '„': -0.36,
    '«': -0.12, '「': -0.62, '『': -0.62,
}


def reporting_strength(token):
    word = token.strip()
    if word.isupper():
        return 0.0
    if word.lower() in REPORTING or word.endswith(CHINESE_SPEECH):
        return 1.0
    return 0.55 if word.lower() in MENTIONING else 0.0


def lead_in(token):
    """Adjustment, and whether punctuation separates attribution from quote."""
    word = token.strip()
    if not token:
        return 0.66, False
    if not word:
        return (-0.10 if '\n' in token else 0.55), False
    if word.endswith(('":', "':")):
        return -0.43, False
    if word.endswith(('\",', "',", '”,', ',”')):
        return 0.17, False
    if word[-1] in ':：,，.!?。！？':
        return (-1.17 if word[-1] in ':：' else
                -0.49 if word[-1] in ',，' else -0.15), True
    if word in ('==', '!=', '===', '!==', '+', '<<', '|', '&'):
        return 0.40, False
    if word[-1] in '({[' or word.isdigit():
        return 0.33, False
    strength = reporting_strength(token)
    if strength:
        return (-3.15 if strength == 1.0 else -1.42), False
    if word.lower() in NAMING or word.endswith(('称', '稱', '提到', '提出')):
        return -1.39, False
    if word.lower() == 'that':
        return -1.56, False
    if word.lower() in TERMS or word.lower() in COPULAS:
        return -0.35, False
    return 0.0, False


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.lstrip()
    if not text:
        return None, 0.0
    t, doc = prefix.position, prefix.document_ids[-1]
    prev = ''
    if t and prefix.document_ids[t - 1] == doc:
        prev = prefix.token_strings[t - 1]
    colon = prev.rstrip().endswith((':', '：'))
    if token == '"':
        return None, -1.4 if colon else -0.28 if '\n' in prev else 0.04
    if text == '```' or (token[:1].isspace() and text.startswith('`')):
        return None, -0.8 if colon else -0.1
    embedded_colon = text.startswith('：“')
    if embedded_colon:
        base = -0.88
    elif text.startswith(('，“', '。“')):
        base = -0.58
    elif text[0] in LEFT_QUOTES:
        base = LEFT_QUOTES[text[0]]
        if text != token and text[0] in '“‘':
            base -= 0.53 if text[0] == '“' else 0.26
    elif text.startswith(('="', "='")):
        extra = 1.25 if prev.strip() in ('style', 'rel') else 0.0
        return None, -0.21 - extra
    elif text.startswith((':"', ":'", ':\\"')):
        base = -0.49
    elif text.startswith(('"""', "'''")) and text != token:
        base = -0.70
    elif text.lstrip('\\').startswith('"') and text != token:
        base = -0.33 if text.startswith('\\') else -0.38
    elif text.startswith('"') and len(text) > 1 and text[1].isalpha():
        base = -0.38
    elif text.startswith("'") and text != token:
        base = 0.0
    else:
        return None, 0.0
    if len(text) > 1 and text[0] in '\"\'“‘' and text[1] in ',.:;)]}':
        return None, 0.0
    adjustment, punctuated = lead_in(prev)
    recent = 0.0
    if embedded_colon:
        adjustment, punctuated = -1.17, True
    if not reporting_strength(prev) or embedded_colon:
        for j in range(t - 1, max(t - 13, -1), -1):
            if prefix.document_ids[j] != doc:
                break
            strength = reporting_strength(prefix.token_strings[j])
            recent = max(recent, strength * 0.88 ** (t - j - 1))
    return None, base + adjustment - (2.80 if punctuated else 1.17) * recent

programs.haiku:
"""Opening quotation marks that introduce speech or a quotation in prose.

Unit 4949 of layer 0's MLP down projection is strongly negative on the token
that OPENS a quotation (" “ ‘ „ 「 « and the like) and is near zero elsewhere,
in particular on closing quotes and on quote marks inside code, JSON or
tool-call text. How negative depends on what comes just before the quotation:
  * a speech verb within the last two words ("said", "says", "explains that",
    "the problem says"): strongly negative (about -3.2); a little further back
    it is weaker (about -1.5, then -0.9 up to 12 words back);
  * a colon with no speech verb before it: moderately negative (-1.7);
  * a comma, period, "as" or "is": moderately negative (-1.2);
  * a closing-quote-and-comma (",) or JSON key (":) before it: weak (-0.3);
  * other opening quotes in prose: mildly negative (-0.5);
  * opening quotes in code-like text (braces, brackets, semicolons, newlines
    in code): about -0.2; a quote mark right after indentation: 0.
Every other token predicts 0.
"""

from collections.abc import Mapping

READS = ()

OPENERS = ('"', "“", "‘", "„", "「", "«", '\\"', "：“", "，“")
SPEECH_WORDS = {
    "say", "says", "said", "saying", "explain", "explains", "explained",
    "asks", "asked", "replied", "added", "adds", "according", "told", "tells",
    "wrote", "writes", "termed", "states", "stated", "answered", "called",
    "calls", "titled", "that", "problem", "quote", "quoted",
}
CODE_MARKS = set("{}[];=<>()\n") | {"tool_call"}
SPEECH_LOOKBACK = 12   # tokens searched for a speech verb
CONTEXT = 30           # tokens of history kept between steps


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    value = 0.0
    core = tok.strip()
    prev = history[-1] if history else ""
    pv = prev.strip()
    opens = core in OPENERS and (
        tok[:1] == " " or tok[:1] in "“‘„「«：，" or pv == "" or prev[-1:] in "([{:=,"
    )
    if opens:
        since = None
        for k, h in enumerate(reversed(history[-SPEECH_LOOKBACK:])):
            if h.strip().lower() in SPEECH_WORDS:
                since = k + 1
                break
        codey = any(m in "".join(history) for m in CODE_MARKS)
        if since is not None and since <= 2:
            value = -3.2
        elif since is not None and since <= 6:
            value = -1.5
        elif since is not None:
            value = -0.9
        elif pv.endswith((":", "：")):
            value = -1.7
        elif pv == "" and "\n" not in prev:
            value = 0.0
        elif pv in ('",', '":', "',"):
            value = -0.3
        elif pv in (",", ".", "as", "is"):
            value = -1.2
        elif codey:
            value = -0.2
        else:
            value = -0.5
    history = (history + (tok,))[-CONTEXT:]
    return (doc, history), value

programs.luna:
"""Approximate the component's response to starting a quoted passage.

The main cue is an opening quotation mark at the current token. For straight
double quotes, nearby whitespace helps distinguish an opener from other uses;
curly and Japanese opening marks have their own strengths. Most other tokens
get zero, so this captures the recurring quote-start pattern rather than all
of the context-dependent activity.
"""

READS = ()

OPEN_DOUBLE_QUOTES = '“„«‹「『'
OPEN_SINGLE_QUOTES = '‘‚'


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    stripped = token.lstrip()
    if not stripped:
        return None, 0.0

    mark = stripped[0]
    has_previous = (
        len(prefix.token_strings) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = prefix.token_strings[-2] if has_previous else ""
    previous_space = bool(previous and previous[-1].isspace())
    previous_letter = bool(previous and previous[-1].isalpha())
    previous_punctuation = bool(
        previous
        and not previous[-1].isspace()
        and not previous[-1].isalpha()
        and not previous[-1].isdigit()
    )

    if mark == '"':
        tail = stripped[1:]
        if token != stripped:
            # A second whitespace boundary is not a reliable opening cue.
            if previous_space:
                return None, 0.0
            if not tail:
                if previous_letter:
                    return None, -0.8
                if previous_punctuation:
                    return None, -0.55
                return None, -0.65
            if not tail[0].isspace():
                if tail and previous_letter:
                    return None, -0.8
                if tail and previous_punctuation:
                    return None, -0.4
                return None, -0.2
        elif previous_space:
            # The space before a quote can be in the preceding token instead.
            if not tail or not tail[0].isspace():
                return None, -0.55 if tail else -0.35
        return None, 0.0

    if mark == '“':
        if token != stripped and previous_punctuation:
            return None, -1.5
        if token != stripped and previous_letter:
            return None, -1.1
        return None, -0.6 if token == stripped else -1.0
    if mark == '„':
        return None, -0.6 if token != stripped else 0.0
    if mark == '«':
        return None, -0.35
    if mark == '「':
        return None, -1.0
    if mark == '『':
        return None, -0.6
    if mark in OPEN_SINGLE_QUOTES and token != stripped:
        return None, -0.8
    if mark == '‹':
        return None, -0.4

    return None, 0.0

programs.sol:
"""A short ENT spelling-chunk detector with weaker ANT/ONT/UNT responses.

ENT is strongest when it fills most of a token, including Cyrillic ЕНТ.
Additional letters dilute it; ordinary MENT/IENT continuation suffixes
are weaker. Selected ENT stem families retain a response in longer tokens.
GOING, WENT and SEND are lexical extensions. For detached endings, a short
preceding stem strengthens the response. State counts the current word's
letters, resetting at document boundaries. Unmatched tokens predict zero.
"""
import re

READS = ()
CYRILLIC = str.maketrans({'е': 'e', 'н': 'n', 'т': 't',
                         'а': 'a', 'о': 'o', 'м': 'm'})


def spelling_score(token):
    space = token.startswith(' ')
    s = token.strip().lower().strip('_./(-')
    cyrillic = 'ент' in s
    s = s.translate(CYRILLIC)
    if s == 'going':
        return -1.2
    if s == 'went':
        return -1.98 if space else -3.9
    if s == 'nt':
        return -1.60
    if s == 'ント':
        return -1.45
    if 'ent' in s:
        i = s.index('ent')
        left, right = s[:i], s[i+3:]
        strength = 3.6
        if len(left) == 1:
            strength = 3.3
            if left == 'c':
                strength = 3.95
            elif left == 'r':
                strength = 2.6
            elif left == 'i':
                strength = 2.5 if right in ('a', 'o') else 1.05
            elif left == 'm' and not space:
                strength = 1.25 if cyrillic else 0.65
        elif len(left) >= 2:
            strength = 0.15 * 0.70 ** (len(left) - 2)
            if left in ('id', 'ar', 'or', 'ud', 'qu', 'li'):
                strength = 2.05
            elif left in ('ag', 'par', 'pat', 'tal', 'sil'):
                strength = 1.25
            elif left in ('dec', 'desc', 'int', 'perc'):
                strength = 1.9
            elif left == 'ind':
                strength = 3.1
        if right:
            strength *= 0.55 ** len(right)
            if right in ('s', 'a', 'i'):
                strength *= 1.40
            elif right.startswith('h'):
                strength *= 0.15  # Ordinal endings such as -teenth.
        if s.startswith(('invent', 'equivalent')):
            strength = 0.75
        if s == 'spent':
            strength = 1.1
        if s == 'mental' and space:
            strength = 2.4
        if s.startswith('cent') and len(s) > 4 and right != 's':
            strength = 0.85 if s.startswith('centur') else 0.10
        if cyrillic and len(left) == 0:
            strength *= 0.88
        return -strength
    m = re.search('[aou]nt', s)
    if m:
        left, right = s[:m.start()], s[m.end():]
        vowel = s[m.start()]
        if len(left) <= 1 and not (left == 'w' or vowel == 'o' and left in ('s', 'c')):
            if s == 'ont' and space:
                return -0.27
            if vowel == 'a' and right == 'a' and not space:
                return -2.2
            if right in ('h', 'i'):
                return -0.12
            return -1.0 * 0.5 ** len(right)
        if s.startswith(('grant', 'warrant', 'elegant')) or s == 'quant':
            return -0.8
    if re.fullmatch(r'(es)?lint|rint', s):
        return -1.1
    if s.startswith('send'):
        return -1.1 if len(s) < 5 else -1.5
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous_letters = 0 if carry is None or carry[0] != doc else carry[1]
    value = spelling_score(token)
    # For a detached word ending, the amount of stem already written matters.
    short = token.lower()
    if short in ('ent', 'ents', 'ент', 'ant', 'ient'):
        n = previous_letters
        if short in ('ent', 'ents', 'ент'):
            strength = 4.2 if n == 0 else max(2.2, 4.7 - 0.38 * max(0, n - 2))
            if short == 'ents':
                strength *= 0.77
            elif short == 'ент':
                strength *= 0.86
            value = -strength
        elif short == 'ant' and n:
            value = -(1.7 - 0.14 * min(n, 9))
        elif short == 'ient' and n:
            value = -2.2 / n ** 0.6
    tail = re.search(r'[^\W\d_]+$', token)
    if tail is None:
        letters = 0
    elif tail.start() == 0:
        letters = min(32, previous_letters + len(token))
    else:
        letters = min(32, len(tail.group()))
    return (doc, letters), float(value)

programs.luna:
"""Approximate a recurring negative signal with familiar word-piece spellings.

Bare pieces such as ``cent`` and ``ent`` are strong cues; nearby ``-nt``
fragments are weaker ones.  This is a spelling proxy, not a context model.
"""

READS = ()


def step(carry, prefix, upstream):
    spelling = prefix.token_strings[-1].strip().lower()

    if spelling in ("cent", "ent", "sent"):
        return None, -3.5
    if spelling.startswith(("cent", "zent", "vent")):
        return None, -0.7
    if spelling.startswith(("ent", "sen", "ant", "ment")):
        return None, -1.0
    if spelling == "going":
        return None, -1.2
    if spelling.endswith("nt"):
        return None, -0.3
    return None, 0.0

programs.sol:
"""Approximate the dominant negative response to short 'ta' spellings.

This is a token-spelling detector, not a meaning detector. It distinguishes
vowel/consonant fragments ending in ta, the prefix meta, and ta spellings
in several scripts. Longer words generally respond less strongly. It also
handles runs of five or six hash marks. Weak background responses and most
split UTF-8 characters are deliberately left at zero.
"""
import re

READS = ()

VOWEL_TA = {
    'ata': -0.81, 'eta': -1.35, 'ita': -1.95,
    'ota': -1.95, 'uta': -1.08,
}
TA_ONSETS = {
    'tab': -1.1, 'tan': -1.25, 'tar': -0.8,
    'tal': -0.6, 'tap': -0.55, 'tang': -0.45,
}
GREEK_LETTERS = {'beta': -0.7, 'delta': -0.55, 'theta': -0.5}
TA_SPELLINGS = {
    'タ': -2.25, 'た': -0.46, '타': -3.4, 'та': -0.57,
    '他': -0.67, '它': -0.67, '她': -0.35, '塔': -2.5,
}
CLUSTER_TA = {
    'n': -1.2, 't': -1.6, 'r': -1.0,
    's': -0.8, 'l': -0.7, 'h': -1.7,
}


def token_value(s):
    word = s.strip().strip('._-/(:[<>\\\t')
    w = word.lower()
    boundary = s != s.lstrip()
    if w == 'meta':
        return -2.85
    if w.startswith('metal'):
        return -0.9 if w == 'metal' else -0.6
    if w.startswith('metast'):
        return -1.2
    if w.startswith('meta'):
        return -0.4
    if w == 'etal':
        return -1.05
    if w == 'tá':
        return -1.1
    if w == 'éta':
        return -1.6
    if w == 'ta':
        if word.isupper():
            return -2.0 if boundary else -2.7
        return -2.8 if word != w else -2.15
    if w in VOWEL_TA:
        return VOWEL_TA[w] - (0.85 if word.isupper() else 0.0)
    if re.fullmatch(r'[aeiou]?[ntrslh]ta[s]?', w):
        base = w[:-1] if w.endswith('s') else w
        return CLUSTER_TA[base[-3]] * (0.75 if boundary else 1.0)
    if w.endswith('s') and w[:-1] in VOWEL_TA:
        return VOWEL_TA[w[:-1]] * 0.8
    if w in TA_ONSETS:
        return TA_ONSETS[w]
    if w in GREEK_LETTERS:
        return GREEK_LETTERS[w] * (1.0 if boundary else 0.55)
    if w == 'santa':
        return -1.0
    if w == 'tangent':
        return -0.57
    if s.strip() in TA_SPELLINGS:
        return TA_SPELLINGS[s.strip()]
    if s.endswith('タ') and len(s) == 2:
        return -1.18 if s[0] == 'ー' else -0.8
    if s.startswith('タ') and len(s) == 2:
        return -0.6
    if w == 'ита':
        return -1.1
    if 5 <= len(s) <= 6 and set(s) == {'#'}:
        return -min(2.8, 0.75 * (len(s) - 2))
    return 0.0


def step(carry, prefix, upstream):
    return None, float(token_value(prefix.token_strings[-1]))

programs.haiku:
"""Component layers.0.mlp.down_proj:4951, a "ta"-syllable detector.

Its activation is strongly negative on tokens that are the syllable "ta" (ta, TA, Ta, meta,
Katakana タ, and the Chinese/Japanese/Russian "ta" characters), and on short word
fragments ending in "ta" (ita, eta, ota, ata, atta, enta). Longer or spaced words that merely
contain "ta" (data, table, take) stay near zero. Two smaller effects: the "meta" prefix
(metal, metadata) is mildly negative, and runs of five or six "#" are strongly negative.
Replacement characters (U+FFFD, a broken multi-byte character) written inside Korean text
are mildly positive. Everything else is predicted as 0.

The program reads only the newest token (and, for the Korean rule, the text just before it).
"""

import re
import unicodedata

READS = ()

# The bare syllable "ta" as its own token, in any case, or Katakana タ.
TA_SYLLABLE = {"ta", "meta", "タ"}
# "ta" as a character in other scripts: 他 it, 它 it, 達/塔 tat-, た ta, та ta.
TA_OTHER_SCRIPT = {"他", "它", "た", "та", "達", "塔"}
COMMON_WORDS = {"data"}  # ends in "ta" but is one ordinary word, not a fragment


def in_hangul_context(text):
    return any(unicodedata.name(c, "").startswith("HANGUL") for c in text)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    x = token.strip().lower()
    t = prefix.position
    if x in TA_SYLLABLE:
        value = -2.3
    elif token in TA_OTHER_SCRIPT:
        value = -0.7
    elif re.fullmatch(r"#{5,6}", x):
        value = -2.2
    elif x.startswith("meta"):
        value = -0.6
    elif x in COMMON_WORDS:
        value = 0.0
    elif x.endswith("ta") and len(x) <= 3 and not token.startswith(" "):
        value = -1.3
    elif x.endswith("ta"):
        value = -0.5
    elif token == "\ufffd" and t > 0 and in_hangul_context(prefix.text_prefixes[t - 1][-12:]):
        value = 0.3
    else:
        value = 0.0
    return None, value

programs.sol:
"""Approximate English auxiliary-to-continuation responses.

The main positive cases are inverted subjects ("can you", "how do I"),
modal negation/adverbs, and objects after "let" and supporting verbs.
"Must", "because", and "cannot" have lexical baselines. Infinitives and
word-internal continuations after auxiliaries are usually much weaker.
Only two previous tokens are kept, with a reset at document boundaries;
other lexical and multilingual responses are not modeled.
"""
READS = ()

# Following "you", "I", "not", and "be": empirical grammatical-role strengths.
AUXILIARIES = {
    'can':    (5.10, 4.00,  2.41, -0.07),
    'could':  (4.30, 3.00,  1.51,  0.12),
    'would':  (4.55, 3.70,  1.41, -0.11),
    'will':   (4.00, 2.60,  1.84, -0.05),
    'should': (3.50, 3.45,  1.10, -0.29),
    'may':    (3.40, 3.40,  1.73,  0.17),
    'might':  (3.00, 2.60,  1.28,  0.29),
    'shall':  (3.00, 2.60,  1.67, -0.13),
    'must':   (3.00, 3.00,  1.50, -0.14),
    'do':     (3.00, 2.25, -0.14, -0.18),
    'does':   (3.20, 2.20, -0.11, -0.18),
    'did':    (2.50, 1.55, -0.26, -0.18),
}
SUBJECT_GAIN = {
    'you': 1.0, 'we': 0.85, 'it': 0.75, 'he': 0.65, 'she': 0.65,
    'they': 0.60, 'there': 0.60, 'anyone': 0.60, 'someone': 0.48,
    'anybody': 0.58, 'somebody': 0.48,
}
DETERMINER_GAIN = {
    'the': 0.63, 'a': 0.33, 'an': 0.33, 'this': 0.49, 'that': 0.18,
    'these': 0.4, 'those': 0.4, 'one': 0.72, 'my': 0.4, 'your': 0.44,
    'his': 0.4, 'her': 0.4, 'our': 0.4, 'their': 0.4, 'any': 0.4,
}
ADVERB_RESPONSE = {
    'also': 0.85, 'only': 1.15, 'now': 1.95, 'probably': 1.65,
    'definitely': 1.5, 'certainly': 1.3, 'just': 0.4, 'really': 0.45,
    'still': 0.55, 'even': 0.8, 'likely': 1.2, 'never': 1.15,
    'best': 1.8, 'otherwise': 1.4, 'all': 1.3, 'almost': 1.4,
    'no': 2.1, 'neither': 2.1, 'possibly': 1.1, 'ever': 1.1,
}
OBJECTS = {'me', 'us', 'him', 'her', 'them', 'it', 'you'}
NEGATIVE_ENDINGS = {"'t", '’t', "n't", 'n’t', 'nt'}
SUPPORT_VERBS = {
    'make', 'makes', 'made', 'making', 'help', 'helps', 'helped',
    'helping', 'doing', 'allow', 'allows', 'allowed', 'letting', 'lets',
}


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    word = raw.strip().lower()
    prev_raw, before = carry[1:] if carry and carry[0] == doc else ('', '')
    prev = prev_raw.strip(' \t\n\r"“”.:;!?').lower()
    whole = raw.startswith(' ') and word.isalpha()
    value = {'must': 0.91, 'because': 0.65, 'cannot': 0.56}.get(word, 0.0)
    if prev in AUXILIARIES:
        strength, first_person, negative, be = AUXILIARIES[prev]
        if whole and (word in SUBJECT_GAIN or word == 'i'):
            gain = SUBJECT_GAIN.get(word, 0.0)
            value = first_person if word == 'i' else strength * gain
            if word == 'i' and raw.strip() == 'i':
                value *= 0.6
            if prev == 'can' and prev_raw.strip() == 'Can':
                extra = {'you': 1.1, 'i': 0.15}.get(word, 0.4)
                value += extra
            if before == 'how':
                if prev == 'can' and word in {'i', 'we'}:
                    value += 1.1 if word == 'i' else 0.7
                elif prev in {'do', 'would'}:
                    value += 0.7
            elif before == 'why':
                value -= 0.4
        elif whole and word in DETERMINER_GAIN:
            gain = DETERMINER_GAIN[word]
            if word == 'the' and prev in {'do', 'does', 'did'}:
                gain = 0.47 if prev == 'do' else 0.55
            value = strength * gain
        elif word in NEGATIVE_ENDINGS or word == 't':
            value = 1.73 if prev == 'can' else 1.5 if word == 'nt' else 0.7
        elif whole and word in {'not', 'be'}:
            value = negative if word == 'not' else be
        elif whole and word in ADVERB_RESPONSE:
            scale = 1.0 if prev == 'can' else 0.7
            value = ADVERB_RESPONSE[word] * scale
        elif whole and word in {'have', 'do', 'get', 'give', 'need', 'want', 'work'}:
            value = -0.5
        elif whole and word in {'see', 'hear', 'tell', 'say', 'know', 'think'}:
            value = -0.8
        elif not whole and word.isalpha() and len(word) > 1:
            value = -0.7 if prev in {'can', 'will', 'do'} else -0.2
        if whole and word != 'i' and raw.strip()[:1].isupper():
            value *= 0.7
    elif prev == 'let':
        if whole and word in OBJECTS:
            value = {'me': 1.3, 'us': 1.65, 'you': 2.2}.get(word, 1.3)
            value += 0.15 if prev_raw.strip()[:1].isupper() else 0.0
        elif word in {"'s", '’s'}:
            value = 0.96
    elif prev in SUPPORT_VERBS and whole and word in OBJECTS:
        value = 1.0
    elif prev in {'is', 'are', 'was', 'were', 'have', 'has', 'had'}:
        if whole and word in SUBJECT_GAIN:
            value = SUBJECT_GAIN[word]
            value *= 1.8 if prev_raw.strip()[:1].isupper() else 1.0
        elif word == 'to' and prev in {'have', 'has', 'had'}:
            value = 0.35
    elif prev in NEGATIVE_ENDINGS and whole and word in SUBJECT_GAIN:
        value = 1.5 * SUBJECT_GAIN[word]
    elif word in NEGATIVE_ENDINGS and prev.endswith('n'):
        value = 0.7 if prev in {'won', 'couldn', 'wouldn'} else 0.1
    return (doc, raw, prev), float(value)

programs.haiku:
"""Auxiliary-then-subject detector for layer-0 MLP component 4952.

The component is a sparse "question / request" detector. It fires on the word just after
an auxiliary or modal verb, most strongly when that word is the subject of a question:
"Can [you] ...", "Do [you] ...", "how can [I] ...", "Should [the] ...". Rules, with the
typical activation each gives (all other positions give 0):
- modal (can, could, will, would, should, may, might, must, shall) then a subject
  pronoun: about 3 ("you" about 5; one more when the modal opens a sentence);
- modal then a negation ("can't", "will not"): about 1.6;
- modal then an adverb ("can now", "will probably") or a determiner ("should [the]"):
  about 1 to 1.5;
- do/does/did then a subject: about 2 to 3 ("you" 3, I/we/it 2.3, other subjects 1.5);
  "do not" in a statement gives 0 (it is slightly negative in the model);
- be/have verb opening a question ("Is [it]", "Are [you]", "Have [you]"): about 1.5;
- "let me/us", "help you", "make it": about 1 to 1.4 on the object pronoun;
- "must" and "because" on their own: weak, about 0.7 to 0.9.
"""

import re

MODALS = {"can", "could", "will", "would", "should", "may", "might", "must", "shall"}
DO_WORDS = {"do", "does", "did"}
BE_HAVE = {"is", "are", "was", "were", "have", "has", "had"}
PRONOUNS = {"i", "we", "they", "it", "he", "she", "someone", "somebody", "anyone", "anybody",
            "one", "there", "this", "that"}
DETERMINERS = {"the", "a", "an", "your", "my", "all", "no"}
NEGATIONS = {"not", "'t", "’t", "nt"}
ADVERBS = {"now", "only", "probably", "definitely", "certainly", "likely", "never", "also",
           "just", "even", "still", "really", "always", "possibly", "ever"}
CAUSATIVES = {"let", "help", "helps", "helped", "make", "makes", "made", "making"}
OBJECTS = {"me", "us", "you", "it", "them", "her", "him"}

READS = ()


def word(text):
    """The word in one token, lower case, with quotes and spaces removed."""
    return re.sub(r"[^\w'’]", "", text).lower()


def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev_raw = prefix.token_strings[-2]
    prev = word(prev_raw)
    cur = word(prefix.token_strings[-1])
    opens_sentence = re.sub(r"[^\w]", "", prev_raw)[:1].isupper()
    if prev in MODALS:
        if cur == "you":
            return None, 5.0 + (1.0 if opens_sentence else 0.0)
        if cur in PRONOUNS:
            return None, 3.0 + (1.0 if opens_sentence else 0.0)
        if cur in NEGATIONS:
            return None, 1.6
        if cur in ADVERBS or cur in DETERMINERS:
            return None, 1.2
    elif prev in DO_WORDS:
        if cur == "you":
            return None, 3.0
        if cur in {"i", "we", "it"}:
            return None, 2.3
        if cur in PRONOUNS or cur in DETERMINERS:
            return None, 1.5
    elif prev in BE_HAVE and opens_sentence and (cur in PRONOUNS or cur == "you"):
        return None, 1.5
    elif prev in CAUSATIVES and cur in OBJECTS:
        return None, 1.4 if cur == "me" else 1.0
    elif prev == "let" and cur in {"'s", "’s"}:
        return None, 1.0
    if cur == "must":
        return None, 0.9
    if cur == "because":
        return None, 0.65
    return None, 0.0

programs.luna:
"""Recognize a sparse set of short conversational and grammatical cues."""
READS = ()

QUESTION_STARTERS = {
    "do", "does", "did", "can", "could", "may", "how",
    "what", "where", "who", "why", "should",
}


def step(carry, prefix, upstream):
    current = prefix.token_strings[-1].strip().lower()
    same_document = (
        len(prefix.document_ids) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = (
        prefix.token_strings[-2].strip().lower() if same_document else ""
    )

    if current == "me" and previous == "let":
        return None, 1.4
    if current in {"'s", "’s"} and previous == "let":
        return None, 0.95
    if current == "i" and previous in QUESTION_STARTERS:
        return None, 3.0 if previous in {"do", "how"} else 3.5
    if current == "you" and previous in {"did", "do", "can", "may"}:
        return None, 2.6

    if current == "because":
        return None, 0.65
    if current == "also" and previous in {"can", "may"}:
        return None, 0.7
    if current in {"must", "cannot", "never", "really", "likely"}:
        return None, 0.65
    if current == "not" and previous in {"would", "should"}:
        return None, 1.0

    determiners = {"a", "the", "this", "your"}
    verbs = {"can", "are", "does", "do", "make", "makes"}
    if current in determiners and previous in verbs:
        return None, 0.55
    if current == "it" and previous == "did":
        return None, 1.0
    return None, 0.0

programs.haiku:
"""Words for hitting, striking, attacking, clicking and impact push the activation negative.

The size depends on the word: 'hit/strike' (and Chinese 击/擊, 打击, 合击) are strongest,
attack-type words next, then click/press/impact/collision words, then milder impact words
such as 'shot', 'blow', 'surprised' and 'stress'. Any word containing 'click' counts as a
click word. The token right after a strong word ('hit the', 'click on', 'impact on') is also
pushed negative, a little."""

READS = ()

HIT = {"hit", "hits", "hitting", "strike", "strikes", "striking", "struck", "击", "擊",
       "打击", "撞击", "合击", "点击"}
ATTACK = {"attack", "attacks", "attacked", "attacking", "attacker", "attackers", "assault",
          "assaulted", "assail", "onslaught", "melee", "striker", "hitter", "hitters",
          "knock", "knocked", "knocking", "knockout", "stroke", "strokes",
          "攻击", "攻", "攻打", "进攻", "攻擊", "袭", "襲", "击杀", "敲", "砸", "刺", "咬"}
IMPACT = {"impact", "impacts", "impacted", "impacting", "collision", "collisions", "collide",
          "collided", "press", "pressed", "pressing", "presses", "shock", "shocked", "punch",
          "punches", "beat", "beats", "beating", "stun", "stunning", "stunned", "hammer",
          "slam", "slammed", "bomb", "bombing", "bombard", "碰", "撞", "碰撞", "冲", "衝",
          "激", "刺激", "锤", "炸", "轰炸", "打", "按下"}
MILD = {"shot", "shots", "shooting", "blow", "blows", "bang", "bite", "bitten", "damage",
        "surprise", "surprised", "impressed", "stimulus", "offense", "offensive", "影响",
        "影響", "驚", "惊", "pulse", "stress", "thrilled", "amazed", "wounded"}
FOLLOW = {"the", "on", "a", "an", "to"}

VALUE = {}
for words, v in [(HIT, -4.0), (ATTACK, -2.2), (IMPACT, -1.3), (MILD, -0.6)]:
    for w in words:
        VALUE[w] = v


def word_value(s):
    key = s.strip().lower()
    if key in VALUE:
        return VALUE[key]
    if "click" in key or "keypress" in key:
        return -1.5
    return 0.0


def step(carry, prefix, upstream):
    v = word_value(prefix.token_strings[-1])
    if v == 0.0 and len(prefix.token_strings) > 1:
        before = word_value(prefix.token_strings[-2])
        if before <= -1.3 and prefix.token_strings[-1].strip().lower() in FOLLOW:
            v = -0.7
    return carry, v

programs.sol:
"""Zero digits, repeated zeros, and conversational ending markers.

Most zeros are negative; the immediately preceding digit calibrates that signal.
Two or more consecutive zeros turn it strongly positive, with the third zero
strongest. A zero across a decimal point, comma, or space is weakly positive.
A document consisting only of zeros has a smaller, constant response instead.
Fullwidth digits are normalized; subscript zeros have a weaker version of the
signal. End-of-message markers are positive. Other tokens are set to zero.
"""
READS = ()

# Response to a zero after digits 1 through 9.
AFTER_DIGIT = (-1.06, -0.60, -0.93, -0.85, -0.12,
               -0.94, -1.18, -0.69, -0.90)
# Numeric punctuation: ordinary zero, zero two tokens back, digit influence.
SEPARATORS = {
    '.': (-0.55, 1.05, 0.54, -0.07),
    ',': (-0.14, 0.94, 0.32, 0.08),
    ':': (-0.43, 0.12, 0.00, -0.43),
    '-': (-0.64, 0.29, 0.00, -0.64),
}


def canonical(token):
    if len(token) == 1 and '\uff10' <= token <= '\uff19':
        return chr(ord(token) - ord('\uff10') + ord('0'))
    return ',' if token == '\uff0c' else token


def digit_effect(token):
    if len(token) == 1 and token in '123456789':
        return AFTER_DIGIT[int(token) - 1]
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous, run, position = '', '', 0, 0
    else:
        _, previous, before_previous, run, position = carry
    token = canonical(prefix.token_strings[-1])
    value = 0.0
    if token == '0':
        effect = digit_effect(previous)
        if run == position:  # Nothing but zeros so far in this document.
            value = 1.04
        elif run:
            value = 3.14 if run == 1 else 3.68 if run == 2 else 3.50
        elif effect is not None:
            value = effect + (0.23 if before_previous == '0' else 0.0)
        elif previous in SEPARATORS:
            ordinary, repeated, scale, offset = SEPARATORS[previous]
            earlier_digit = digit_effect(before_previous)
            value = repeated if before_previous == '0' else ordinary
            if earlier_digit is not None:
                value = scale * earlier_digit + offset
        elif previous.isspace():
            value = 0.80 if before_previous == '0' else -0.55
        elif previous.strip() in ('(', '['):
            value = -0.83 if previous.strip() == '(' else -0.67
        else:
            value = -1.05 if previous == '/' else -0.60
    elif token == '\u2080':
        value = 0.67 if position == 0 else 0.95 if previous == '\u2080' else -0.70
    elif token == '<|im_end|>':
        if previous in ('</tool_call>', '</tool_response>'):
            value = 1.48
        else:
            value = 1.30 if '.' in previous or '\u3002' in previous else 1.40
    elif token == '</think>':
        value = 0.19
    run = run + 1 if token == '0' else 0
    return (doc, token, previous, run, position + 1), value

"""A lexical detector for 'this', 'these', and related pointing words.

The response is negative, strongest for Chinese proximal demonstratives.
Different languages/inflections have different strengths. Capitalization and
word boundaries weaken English forms; genitives and 'all/both' strengthen
lowercase forms. Chinese manner/place/plural/copular compounds are weaker
than simple proximal determiners. Unknown tokens, including English 'that',
get zero. Strengths were estimated from training activations. This is a
word-form approximation, not full reference resolution.
"""
READS = ()

# Demonstrative inflections and nearby 'here'/'such' words, grouped by language.
WORDS = {
    'это': -2.0, 'этот': -2.5, 'эта': -3.3, 'эти': -2.1,
    'этого': -3.1, 'этому': -3.9, 'этом': -3.2, 'эту': -3.7,
    'этой': -4.2, 'этим': -3.2, 'этих': -3.1, 'здесь': -1.45,
    'такой': -1.2, 'такие': -1.45, 'таких': -1.55,
    'diese': -1.55, 'dieser': -1.6, 'dieses': -1.75,
    'diesem': -1.3, 'diesen': -1.5,
    'ce': -0.36, 'cet': -0.48, 'ces': -0.64,
    'cette': -1.5, 'cela': -1.36,
    'este': -0.68, 'esta': -0.95, 'estos': -2.2, 'estas': -0.8,
    'esto': -1.46, 'eso': -1.0, 'questo': -1.65,
    'questa': -1.17, 'questi': -1.07, 'ini': -1.9, 'itu': -1.06,
    'này': -2.8, 'đó': -1.26, 'đây': -1.71,
    'هذا': -2.95, 'هذه': -2.65, 'ذلك': -1.58,
}
# Japanese proximal this/here, distal that/there, 'such', and 'called' forms.
JAPANESE = {
    'この': -3.65, 'これ': -4.1, 'ここ': -3.7, 'こちら': -2.25,
    'こういう': -3.75, 'こんな': -3.3, 'その': -0.85,
    'それ': -1.5, 'そこ': -2.2, 'そういう': -2.6,
    'そんな': -1.9, 'という': -2.05,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    first = (prefix.position == 0 or
             prefix.document_ids[-2] != prefix.document_ids[-1])
    previous = '' if first else prefix.token_strings[-2]
    lower = word.lower()
    value = 0.0
    if lower in ('this', 'these', 'those'):
        value = {'this': -2.1, 'these': -2.95, 'those': -1.03}[lower]
        if word[:1].isupper():
            value *= 0.7 if lower != 'those' else 0.9
        if not token[:1].isspace() and lower == 'this':
            value *= 0.75
        if first:
            value *= 0.3
        elif word in ('this', 'these') and token.startswith(' '):
            prev = previous.strip().lower()
            if not prev or not any(c.isalnum() for c in prev):
                value += 0.45
            elif prev == 'of':
                value -= 0.35
            elif prev in ('all', 'both'):
                value -= 0.8
            elif prev == 'like':
                value += 1.0 if word == 'this' else 0.4
            if previous.strip()[:1].isupper():
                value += 0.3
    elif word in ('(this', '$this', '.this'):
        value = -4.7 if word == '.this' else -1.85
    elif lower in WORDS and (first or token[:1].isspace()):
        value = WORDS[lower]
        if word == 'Это':
            value = -2.57
    elif word.startswith(('这', '這')):
        tail = word[1:]
        if not tail:
            value = -7.85
        else:
            value = -7.3 if word[0] == '这' else -6.5
            # Manner/place phrases ('like this', 'here') are weaker.
            if tail.startswith(('样', '樣', '么', '麼', '里', '裡', '儿')):
                value = -4.7
            # Plural, copular, and temporal compounds ('these', 'this is').
            if tail.startswith(('些', '是', '次', '时')):
                value = -5.6
            if tail.startswith(('样的', '樣的')):
                value = -6.5
            elif tail.startswith('边'):
                value = -3.2
            elif tail.startswith(('就是', '也是')):
                value = -5.5
            # Longer fused phrases dilute the single-token pointing signal.
            value = min(-1.8, value + 0.8 * max(0, len(word) - 2))
    elif word.startswith('此'):
        value = -1.6 if word in ('此前', '此后', '此外', '此刻') else -3.6
        if word == '此' and not first:
            before = (prefix.text_prefixes[-2][-1:]
                      if '\ufffd' in previous else previous[-1:])
            if before == '因':
                value = -0.25  # 因此 means 'therefore', not 'this'.
    elif word.startswith(('在这', '在這', '但这', '而这')):
        value = -4.8 + 0.5 * max(0, len(word) - 2)
    elif word in ('如此', '对此', '在此', '今年', '上述'):
        value = {'如此': -1.8, '对此': -2.8, '在此': -1.9,
                 '今年': -1.1, '上述': -1.2}[word]
    elif word in ('该', '該', '那'):
        value = -1.0
    else:
        for stem, strength in JAPANESE.items():
            if word.startswith(stem):
                value = min(-0.5, strength + 0.4 * (len(word) - len(stem)))
                if word == 'これまで':
                    value = -0.15  # 'until now', not an object demonstrative.
                break
        if '\ufffd' in token:
            # Recover a character completed by a byte token.
            value = {'这': -8.6, '這': -3.5}.get(
                prefix.text_prefixes[-1][-1:], value)
    return None, float(value)

programs.luna:
"""A negative response to common demonstrative and pointing words.

The clearest responses are to English this, these, and those. A few
sampled German, Russian, Chinese, and Vietnamese forms show the same
pattern; several connective phrases have smaller responses.
"""
READS = ()

POINTING_WORDS = {
    "this": -2.1, "these": -2.8, "those": -1.1,
    "diesem": -1.4, "dieses": -1.9,
    "этого": -2.9, "эту": -4.0, "это": -2.0,
    "这些": -4.0, "những": -0.3,
}
CONNECTIVES = {"ですから": -0.8, "と言い": -0.7, "因此": -0.6}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return None, POINTING_WORDS.get(word, CONNECTIVES.get(word, 0.0))

programs.sol:
"""Mark source, destination, and result phrases rather than ordinary infinitives.

'Lead to' and 'result in' are the strongest patterns. A single intervening
word weakens them. Other explicit relations have smaller responses. The
program also recognizes 'from', 'towards', and a few common verb-particle
phrases. It ignores the component's many small, idiosyncratic responses.
"""
import re

READS = ()
LEAD = set('lead leads led leading'.split())
RESULT = set('result results resulted resulting'.split())
CONTRIBUTE = set('contribute contributes contributed contributing'.split())
TRANSLATE = set('translate translates translated translating'.split())
RELATION_TO = set('''
    due owing subject subjected prior adjacent addition response responses
    refer refers referred referring relate relates relating equivalent rise
    contribution contributions pertaining entitlement entitled attributed
'''.split())
CONNECTION_TO = set('''
    apply applies applied applying add adds added adding compare compared
    comparison contrast proportional regard regards reference connect
    connects connected connection link linked convert converted map mapped
    mapping forward respond responds exposed pursuant point points next
    resemblance similar similarity related relative parallel opposed
    attach attached assign assigned transfer transferred sensitive thanks
    solution approach belong belongs belonging attention used adhere coupled
'''.split())
INFINITIVE_CUES = set('''
    meant designed asked encouraged happy excited required allowed necessary
    decided free failure time ways
'''.split())
ACTIVITY_IN = set('''
    shown illustrated depicted summarized reflected live lived living engage
    engages engaged engaging run runs running serve served serving
'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    words = re.findall(r'[a-z]+', tail.lower())[-2:]
    match = re.search(r'([a-z]+)\s*$', tail.lower())
    prev = match.group(1) if match else ''
    before = words[-2] if len(words) > 1 else ''
    word = token.strip().lower()
    value = 0.0
    if word.lstrip('._(') == 'from':
        value = 0.84 if token == ' from' else 1.1
        if prev in RESULT:
            value += 1.0
        elif prev in {'away', 'apart'}:
            value = 0.4
    elif word in {'toward', 'towards'}:
        value = 0.74
    elif token == ' to':
        value = 0.06
        if prev in LEAD:
            value = 6.65
        elif before in LEAD:
            value = 3.25
        elif prev in CONTRIBUTE:
            value = 2.95
        elif before in CONTRIBUTE:
            value = 1.65
        elif prev.startswith('correspond'):
            value = 2.15
        elif prev in {'amount', 'amounts', 'amounted', 'amounting'}:
            value = 2.7
        elif prev in RELATION_TO:
            value = 1.55
        elif prev in CONNECTION_TO:
            value = 1.05
        elif prev in INFINITIVE_CUES:
            value = -0.55
        elif prev in {'order', 'respect', 'equal', 'access', 'likely'}:
            value = 0.4
    elif token == ' in':
        if prev in RESULT or prev.startswith('culminat'):
            value = 6.35
        elif before in RESULT:
            value = 2.1
        elif prev in {'help', 'helps', 'aid', 'aids', 'assist'}:
            value = 2.0
        elif prev in {'end', 'ends', 'ending', 'ended', 'finished'}:
            value = 1.6
        elif prev in ACTIVITY_IN:
            value = 1.0
        elif prev in {'used', 'involved', 'interested', 'available', 'role'}:
            value = 0.35
    elif token == ' into':
        value = 0.14
        if prev in TRANSLATE or before in TRANSLATE:
            value = 2.8
        elif prev in {'turn', 'turns', 'turned', 'run', 'ran'}:
            value = 1.35
    elif token == ' as' and prev in {'serve', 'serves', 'served', 'serving'}:
        value = 1.4
    elif token == ' by' and prev == 'followed':
        value = 0.9
    elif word == 'out' and prev in {'point', 'points', 'pointed', 'pointing'}:
        value = 0.8
    elif word == 'up' and prev in {'end', 'ends', 'ending', 'ended'}:
        value = 0.75
    return (doc, (tail + token)[-80:]), float(value)

programs.haiku:
"""Layer-0 MLP output feature: a preposition ("to", "in", "into", "from", "towards") that
completes a verb or noun of causing, resulting or correspondence.

Strongest on "lead(s/ing/led) to" and "result(s/ed/ing) in" (about 6.5), moderate on
"due / contribute / correspond / prior / compared / referred / related ... to" and
"help / reflected / shown ... in" (about 1.5), weak but steady on "from" (about 0.9) and
"towards" (about 0.7), slightly negative on infinitive "to" ("asked to", "meant to",
about -0.6), and near zero on all other tokens. """
READS = ()

LEAD = {"lead", "leads", "led", "leading"}                     # lead to
RESULT = {"result", "results", "resulted", "resulting"}       # result in
TO_LINKS = {                                                  # X to
    "due", "owing", "contribute", "contributes", "contributed", "contributing",
    "contribution", "corresponds", "corresponding", "correspond", "equivalent",
    "relates", "relate", "related", "relating", "refers", "referred", "prior",
    "adjacent", "addition", "subject", "subjected", "applied", "response", "responds",
    "respond", "compared", "similar", "added", "used", "pertaining", "connected",
    "points", "predisposed", "entitlement", "rise",
}
IN_LINKS = {"shown", "reflected", "help", "helps", "aid", "aids", "assist", "involved",
            "depicted", "illustrated", "culminated", "up"}
INFINITIVE = {"asked", "asks", "ask", "meant", "decided", "designed", "happy", "excited",
              "return", "returned", "time", "failure", "required", "call", "called"}
OBJECTS = {"them", "us", "him", "her", "me", "you", "it", "groups", "people"}


def clean(s):
    return s.strip().lstrip("-_./\t").lower()


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    word = clean(strings[-1])
    prev = clean(strings[-2]) if len(strings) > 1 else ""
    prev2 = clean(strings[-3]) if len(strings) > 2 else ""
    if word in ("to", "toward", "towards"):
        if word != "to":
            return None, 0.7
        if prev in LEAD:
            return None, 6.5
        if prev in OBJECTS and prev2 in LEAD:
            return None, 3.0
        if prev in TO_LINKS:
            return None, 1.5
        if prev in INFINITIVE:
            return None, -0.6
        return None, 0.1
    if word == "in":
        if prev in RESULT:
            return None, 6.5
        if prev in IN_LINKS:
            return None, 1.0
        return None, 0.0
    if word == "into":
        return None, 0.4
    if word.endswith("from"):
        return None, 0.9
    return None, 0.0

programs.luna:
"""Estimate a directional word's activation, with extra weight when 'to' follows
language about linking, applying, adding, or transferring something.
