VOWELS = frozenset('AEIOUaeiou')


def response(token, previous, word):
    n = 0
    for ch in reversed(previous):
        if not ch.isupper():
            break
        n += 1
    extra = min(4, max(0, len(word) - n))
    spaced = previous.startswith(' ')
    prev_vowel = any(ch in VOWELS for ch in previous)
    token_vowel = any(ch in VOWELS for ch in token)
    title_start = word.istitle() and len(word) in (2, 3)
    if token == 's':
        return (0.48, 1.10, 0.73)[n-1] if 1 <= n <= 3 else (
            0.45 if n >= 4 else -0.04)
    if token.isdigit():
        return -0.08 if n >= 2 else 0.0
    if token.startswith('&') and token[1:].isupper() and n:
        return 0.6
    if not (token.isalpha() and token[0].isupper()):
        return 0.0
    if len(token) == 2 and token[1] == 's':
        if previous.endswith('&'):
            return 1.3
        if n:
            return 3.1 - 0.3 * extra
        return 0.47 if not previous else (
            0.75 if title_start and len(word) == 2 else -0.05)
    if token.isupper() and len(token) == 1:
        if not n:
