                0.23 if title_start and len(word) == 2 else -0.03)
        base = (0.88, 1.19, 0.77)[n-1] if n <= 3 else 0.12
        decay = (0.055, 0.10, 0.02)[n-1] if n <= 3 else 0.0
        vowel_penalty = (0.21 if n == 2 else 0.41) if n in (2, 3) else 0
        value = base - decay * extra - vowel_penalty * prev_vowel
        value += 0.11 * spaced - 0.07 * token_vowel
        value -= 0.52 * (token in ('X', 'Y')) + 0.24 * (not token.isascii())
        return max(0.02, value)
    if token.isupper() and len(token) == 2:
        if n not in (1, 2):
