        return ((0.34 if n == 1 else 0.19) - 0.05 * (extra > 0)
                + 0.22 * (spaced and n == 1) - 0.07 * prev_vowel - 0.14 * token_vowel
                - 0.26 * (not token.isascii()))
    if not token.isupper() and n:
        return (0.9 if len(token) == 2 else
                0.45 if len(token) == 3 else 0.3)
    return 0.0


