    doc = prefix.document_ids[-1]
    previous, word = carry[1:] if carry and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    value = response(token, previous, word)
    for ch in token:
        word = (word + ch)[-20:] if ch.isalpha() else ''
