            stack = stacks[closer]
            span = position - stack[-1] if stack else 1000
            space = token.startswith(' ')
            lines = min(token.count('\n'), 2)
            empty = any(OPEN_TO_CLOSE.get(c) == closer for c in before)
            reopening = any(c in '[{' for c in after)
