                    if '"' in before or "'" in before:
                        value += -0.95 + near
                    if '"' in after or "'" in after:
                        value += -0.3 + near
                    if any(c in ')]' for c in before):
                        value += -0.5 + 1.4 * near
                    if ')' in after:
                        value += -0.3 + 1.45 * near
                    if '$' in after:
                        value += -0.15 + 1.75 * near
                if not stack and not reopening and not empty:
                    value += 1.8 / (1 + position / 10) - 0.3
            elif closer == ']':
                value = -1.8 + 0.60 * math.log1p(min(span, 32))
                if lines:
                    value = 0.1 - 0.9 * math.exp(-span / 14)
                if reopening:
                    value = -0.4
                if '(' in after:
                    value = -0.1
                if '"' in before or "'" in before:
