"""layers.0.mlp.down_proj:4967 explained as a relational-preposition detector.

The component writes a strongly negative value into the residual stream on words
that place something relative to a location or a sequence: "above" and "below"
(about -7), then "before", "beyond", "behind", "inside", "outside", "within",
"ahead" (about -1.7), then "after", "here", "follow(ing)", "between", "among"
(about -0.6). Everywhere else it is near zero. The value depends on the word
alone; the surrounding context changes it very little.
"""

READS = ()

# Words that place something above or below a reference point, the strongest case.
VERTICAL = {"above", "below", "beneath", "underneath"}
# Spatial and sequence prepositions that take an object: "before the war", "inside the box".
SPATIAL = {"before", "beyond", "behind", "inside", "outside", "within", "ahead"}
# Weaker cases: "after", "here", "following", "between", "among".
WEAK = {"after", "here", "follow", "follows", "following", "followed", "between", "among"}

STRENGTH = {"vertical": -6.9, "spatial": -1.7, "weak": -0.6}


def step(carry, prefix, upstream):
    """Predict the component's activation at the newest token of the prefix."""
    word = prefix.token_strings[-1].strip().lower()
    if word in VERTICAL:
        value = STRENGTH["vertical"]
    elif word in SPATIAL:
        value = STRENGTH["spatial"]
    elif word in WEAK:
        value = STRENGTH["weak"]
    else:
        value = 0.0
    return carry, value

