for above/below and before/after.  The small lexical groups capture this
ordering-and-location signal, not context-specific spikes or background noise.
"""
READS = ()

VERY_STRONG = {"above", "below"}
STRONG = {"before", "outside"}
MEDIUM = {"within", "following", "follows", "follow", "here", "there"}
RELATED = {
    "after", "between", "under", "over", "beneath", "inside",
    "across", "through", "behind", "beyond", "until", "since",
    "better", "greater", "less", "equal", "如下",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    words = token.replace("_", " ").replace("-", " ").split()
    if any(word in VERY_STRONG for word in words):
        value = -5.5
    elif any(word in STRONG for word in words):
        value = -2.0
    elif any(word in MEDIUM for word in words):
        value = -1.0
    elif any(word in RELATED for word in words):
        value = -0.7
    elif token in {">", "<", ">=", "<=", "≥", "≤"}:
        value = -0.7
    else:
        value = 0.0
    return None, value

