"""A lexical INS/insert detector, not a sentence-topic detector.

Bare 'ins', 'insert', and Chinese 插 (insert) have large responses.
Longer ins-word families and plug-in words are weaker. Case and whether
'ins' continues a word matter; a preceding vowel weakens lowercase 'ins'.
Unlisted spellings predict zero, leaving incidental/contextual activity out.
"""
READS = ()

# English word families sharing the prominent INS spelling.
INS_FAMILIES = (
    ("insight", 2.2),
    ("inspector", 1.75),
    ("inspection", 0.85),
    ("inspect", 1.25),
    ("insulin", 1.45),
    ("insider", 1.0),
    ("insurance", 0.85),
    ("insur", 1.35),
    ("insulat", 1.35),
    ("inspir", 0.7),
)
INSERT_FORMS = {
    "inserted": 2.25,
    "insertion": 2.25,
    "inserting": 2.75,
    "inserts": 3.0,
}
RELATED_FRAGMENTS = {
    "inser": 2.15,
    "insk": 1.0,
    "inski": 1.1,
    "imp": 0.8,
    "impl": 0.55,
    "uns": 0.45,
    "üns": 1.0,
    "eins": 1.0,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    word = token.lstrip()
    while word and not word[0].isalpha():
        word = word[1:]
    s = word.lower()
    continues_word = token == word and previous.isalpha()
    value = RELATED_FRAGMENTS.get(s, 0.0)

    if s == "ins":
        if word == "Ins":
            value = 4.55 if token.startswith(" ") else 5.0
        elif word == "INS":
            value = 3.0 if continues_word else 4.5
        elif continues_word:
            value = 1.9 if previous.lower() in "aeiouy" else 2.45
        else:
            value = 4.1
    elif s == "insert":
        value = 4.3 if word.isupper() else 4.1 if token == "insert" else 3.4
    elif s.startswith("insert"):
        value = INSERT_FORMS.get(s, 1.6)
    elif word in {"插", "插入"}:
        value = 3.65
    elif s in {"plugin", "plugins"}:
        value = 1.15 if token.startswith("-") else 1.45
    elif s == "inst":
        value = 0.95 if token.startswith(" ") else 1.4 if continues_word else 1.8
    elif s == "ns":
        value = 0.45 if continues_word else 0.95
    elif s == "inn":
        value = 0.55 if token.startswith(" ") else 0.1
    else:
        for stem, response in INS_FAMILIES:
            if s.startswith(stem):
                value = response
                break
    return (doc, token[-1:]), float(value)

programs.haiku:
"""Layer 0 MLP down-projection component 4968: a word-piece detector for "insert" and the
"ins" stem.

It is almost silent everywhere except on the current token when that token is a piece of
the word "insert" (or its stem "ins": "ins", " Ins", "-ins", " insert", "Insert", " inserted",
" insight"). Those tokens give a strong activation (~3.4). Weaker responses go to other
"ins"-initial pieces (insulin, insurance, inspect: ~0.9), the piece "inst" (~1.4), the word
"plugin"/"plugins" (~1.4, a plugin is a thing you insert), "imp"/"impl" (~0.6) and the piece
"ns" (~0.4). The Chinese character 插 ("insert, plug in") is treated like the insert stem.
Everything else, including "instead", "inside", "instance", is predicted as 0.

The program reads only the newest token's string. It has no carry state.
"""

READS = ()


def activation(token):
    s = token.strip().lower().lstrip(".-_/(")
    if s in ("ins", "插") or s.startswith("insert") or s.startswith("insight"):
        return 3.4
    if s == "inst":
        return 1.4
    if s.startswith("ins") and not s.startswith("inst") and not s.startswith("inside"):
        return 0.9
    if "plugin" in s:
        return 1.4
    if s in ("imp", "impl"):
        return 0.6
    if s == "ns":
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    return carry, float(activation(prefix.token_strings[-1]))

