"""Approximate an action/modifier contrast, not all word-specific background.

After a Chinese modal, manner adverb or passive marker, action stems get a
negative pulse, especially writing/editing stems. Japanese object particles
produce a similar pulse. Auxiliary and locative continuations get positive
pulses instead. Only the previous token is remembered, resetting at documents.
At row/document starts, execution adverbs and how/inability expressions have
positive pulses. Delimiters and English passive participles have extra rules.
"""

READS = ()

EDITING = set('选選写寫画畫填解申改記记读讀算計测測描绘繪')
WRITING_SELECTION = set('选選写寫画畫填申')
WRITING_DRAWING = set('写寫画畫填')
ACTION_STEMS = EDITING | set(
    '交加查拆收打装裝封列摘取押建補补破付买買換换说說談谈'
    '講讲答問问投按洗刷锁鎖推拉插造采採剪切拍烧燒煮烤'
)
ACTION_WORDS = set((
    '回答 支付 确认 確認 整理 分析 访问 訪問 结算 定义 '
    '处理 處理 説明 食べ 食べる 申し込み'
).split())
NOUN_ENDINGS = set('者员員器机機性率量度品物人官学學术術')
MANNER = set((
    '自 相 再 来 來 去 手 代 新 重 先 刚 直接 自动 自動 '
    '进行 进行了 正在 不断 快速 慢慢 好好 免费 在线 一起 '
    '已经 已經 开始 開始 继续 单独 统一 随机 正确 全面 仔细'
).split())
STRONG_MANNER = set((
    '被 所 未 待 乱 亂 瞎 严 嚴 厳 误 誤 难 難 妄 自行 '
    '手工 重新 如何 怎么 怎样 怎麼 详细 詳細 难以 無法 '
    '无法 不用 从未 不予 一经 未经'
).split())
MODAL_ENDINGS = (
    '要', '需要', '可以', '能', '不能', '不', '没', '未',
    '没有', '沒有', '想', '怎么', '怎麼', '如何', '进行', '地',
)
AUXILIARIES = set((
    '在 到 于 於 就 将 將 会 會 能 可以 如何 怎么 怎样 先 '
    '好好 直接 自行 更多 更多的 一步 不用 不能 应该 可能 '
    '没有 不会 不再 还 仍然 已经 正在 在这 在這 那里 这里 '
    '的 地 得 然 そのまま いつ より そう ように できる'
).split())
MARKUP = {
    '<|im_start|>': 0.0735,
    '<think>': -0.1485, '</think>': -0.1485,
    '<tool_call>': -0.1245, '</tool_call>': -0.0585,
    '</tool_response>': -0.0675,
}
PARTICIPLES = set('known found shown seen given made taken done built'.split())


def strong_modifier(word):
    return word in STRONG_MANNER or word.endswith(('怎么', '怎麼', '怎样', '如何'))


def modifies_action(word):
    return bool(word) and (
        word in MANNER or word in STRONG_MANNER
        or word.endswith(MODAL_ENDINGS)
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    before = '' if start else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    stem = word[:1]
    action = word in ACTION_WORDS or (
        1 <= len(word) <= 3 and stem in ACTION_STEMS
        and (len(word) == 1 or word[-1] not in NOUN_ENDINGS)
    )
    value = MARKUP.get(token, -0.0015)
    modifier = modifies_action(before)
    if action:
        if stem in EDITING:
            value -= 0.023
        if modifier:
            value -= 0.115 + 0.116 * (stem in EDITING)
            value -= 0.066 * (len(word) == 1)
            value -= 0.130 * strong_modifier(before)
        if before == 'を':
            value -= 0.304
        elif before == 'で':
            value -= 0.155
        elif before in {'お', 'ご', 'をお', 'にお'}:
            value -= 0.188
    # Single writing/selection stems are stronger than merged action words.
    if len(word) == 1 and modifier:
        if word in WRITING_SELECTION or word == '解':
            value -= 0.200
        if word in WRITING_DRAWING and strong_modifier(before):
            value -= 0.200
    # The Japanese request stem after a polite object prefix is especially strong.
    if word == '申' and before in {'をお', 'にお'}:
        value -= 0.500
    if word == '解' and before == 'を':
        value -= 0.300
    if word in AUXILIARIES:
        if modifier:
            value += 0.059 + 0.080 * strong_modifier(before)
            value += 0.139 * (word in {'在', '在这', '在這', '于', '於'})
        if before == 'を':
            value += 0.248
    if before.lower() == 'been' and (
        word.lower().endswith('ed') or word.lower() in PARTICIPLES
    ):
        value -= 0.073
    if start:
        if word.lower() in {'successfully', 'properly', 'correctly'}:
            value = 0.45
        elif word in {'如何', '怎么', '怎麼', '不能', '无法', '無法'}:
            value = 0.50
    return (doc, word), float(value)

"""Approximate a multilingual spelling-fragment signal, not a topic detector.

Recent completed function words and distinctive letters provide language cues.
Persian long-vowel fragments tend negative; consonant-rich fragments and
several verb/person endings tend positive. Dutch and Romanian have additional signed grammatical
words and suffixes, plus a weaker Cyrillic vowel-ending contrast. Other
vocabulary and fine context dependence are not modeled.
All evidence and the unfinished word reset at document boundaries.
"""
import re
import unicodedata

READS = ()

DUTCH = set('het een zijn voor maar bij niet ook wij mijn jij jouw jullie '
            'naar deze worden hebben wordt heeft zonder kunnen ons uw '
            'kunt dit van'.split())
ROMANIAN = set('pentru este sunt acest aceasta aceste acestui acestora fost '
               'foarte trebuie poate fiecare dintre asupra sau din care '
               'unui unei'.split())
ENGLISH = set('the and with was this you that which'.split())
OTHER_LATIN = set('que el los las una les une pour avec bir ve için'.split())
NOT_DUTCH = (ENGLISH - {'was'}) | OTHER_LATIN | set(
    'pentru este und der das den dem des ein eine im'.split())
NOT_ROMANIAN = ENGLISH | OTHER_LATIN
PERSIAN = set('به در است را می برای'.split())
LONG_VOWELS = set('ایيوىا')


def word_cues(word):
    return (
        .6 * (word in PERSIAN),
        .8 * (word in ROMANIAN)
        + .3 * (word in {'cu', 'si', 'mai', 'nu', 'pe', 'sa', 'la'})
        - .6 * (word in NOT_ROMANIAN),
        .5 * (word in DUTCH)
        + .15 * (word in {'en', 'je', 'met', 'die'})
        - .6 * (word in NOT_DUTCH),
        0.,
    )


def persian_spelling(s, t):
    letters = [c for c in t if '\u0600' <= c <= '\u06ff' and c.isalpha()]
    if not letters:
        return 1.3 * ('\u200c' in t) - .28 * (t == '،')
    n = len(letters)
    boundary = s[0].isspace()
    vowels = sum(c in LONG_VOWELS for c in letters)
    if not boundary and n <= 3 and letters[-1] in LONG_VOWELS:
        return -1.02
    if not boundary and t in {'ه', 'م', 'ند', 'ده', 'نم', 'رم', 'شد', 'ام'}:
        return 1.59
    if vowels / n <= .23:
        if n == 1 and t in 'تسعل':
            return .08
        if 'گ' in t:
            return 1.54
        if boundary and t in {'بر', 'به', 'در'}:
            return 1.23
        return .78
    if boundary and t == 'ا':
        return 1.07
    if n > 1 and all(c not in LONG_VOWELS for c in letters[-2:]):
        return .86
    return .08


ROMANIAN_VOWEL_ENDINGS = {
    'ie', 'iei', 'ia', 'ii', 'ati', 'ți', 'ţi', 'i', 'eni', 'enta'}
ROMANIAN_NEGATIVE_WORDS = {'la', 'cu', 'mai', 'lui', 'sa'}


def romanian_spelling(s, t):
    boundary = s[0].isspace()
    ending = not boundary and t in ROMANIAN_VOWEL_ENDINGS
    if t[-1] not in 'aiou':
        if any(c in 'îâ' for c in t):
            return 1.63
        if ending:
            return -1.89
        if t in {'este', 'sunt', 'trebuie', 'acest', 'fost'}:
            return 1.48
        if t == 'se':
            return 1.93
        nasal_cluster = (len(t) <= 3 and any(c in 'mn' for c in t)
                         and not any(c in 'aeiou' for c in t))
        if nasal_cluster:
            return 1.20
        return .53
    if t[0] == 's':
        return -2.93
    ai_share = sum(c in 'ai' for c in t) / len(t)
    if ai_share <= .27:
        return -.96 if t in ROMANIAN_NEGATIVE_WORDS else .36
    if t == 'au':
        return 1.48
    if t in ROMANIAN_NEGATIVE_WORDS:
        return -1.75
    return -1.11 if ending else -.49


def dutch_spelling(s, t):
    boundary = s[0].isspace()
    if t in {'en', 'van', 'die'}:
        return -.96 if boundary else -.57
    if not boundary and len(t) <= 5 and t.endswith('ie'):
        return -1.75
    if t in {'je', 'jij', 'jou'}:
        return -1.56
    if t[-1] in 'aiou':
        ai_share = sum(c in 'ai' for c in t) / len(t)
        return -.48 if ai_share > .16 else -.15
    if t == 'ver':
        return .88
    if not boundary and t in {'en', 'ens', 'ien', 'ies'}:
        return -.80
    if t in {'in', 'een', 'met', 'op', 'aan', 'naar', 'dit', 'hun', 'zo'}:
        return -.21
    return .05


def cyrillic_spelling(s, t):
    letters = [c for c in t if '\u0400' <= c <= '\u04ff' and c.isalpha()]
    if not letters:
        return -.11 * ('\ufffd' in t)
    n = len(letters)
    return (
        .10 + .07 * s[0].isspace()
        - .16 * sum(c in 'аяию' for c in letters) / n
        - .24 * letters.count('я') / n - .16 * letters.count('ю') / n
        - .13 * (letters[-1] in 'аеиоуыэюяії')
        - .18 * (letters[-1] == 'ь')
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, (0., 0., 0., 0.), '')
    s = prefix.token_strings[-1]
    t = s.strip().lower()
    evidence = [v * d for v, d in zip(carry[1], (.98, .995, .99, .98))]

    # Recognize completed words, including words split across several tokens.
    parts = re.split(r'[\W\d_]+', s.lower())
    word = carry[2] + parts[0]
    if len(parts) > 1:
        for completed in [word] + parts[1:-1]:
            for j, cue in enumerate(word_cues(completed)):
                evidence[j] += cue
        word = parts[-1]
    if len(word) > 32:
        word = ''
    evidence[0] += .5 * any(c in 'پچژگکی\u200c' for c in s)
    evidence[0] -= any(c in 'ےںھہٹڈڑۓ' for c in s)  # Urdu spellings
    evidence[1] += .8 * any(c in 'ășțţ' for c in s)
    evidence[1] += .3 * any(c in 'îâ' for c in s)
    evidence[1] -= .7 * any(c in 'ğışöü' for c in s)
    evidence[1] -= .6 * any(c in 'đĐếềễểệắằẳẵặớờỡởợứừữửựỗồốổộ' for c in s)
    evidence[3] += .4 * any(c in 'іїєґъ' for c in s)
    evidence[3] -= .5 * any(c in 'ыэёѣ' for c in s)
    evidence = tuple(max(0., v) for v in evidence)
    fa = .08 + .92 * min(1., evidence[0])
    ro = min(1., max(0., evidence[1] - 1.5) / 8.)
    nl = min(1., max(0., evidence[2] - 1.5))
    cy = .08 + .92 * min(1., evidence[3])
    value = -.4 if t in {'si', 'asi', 'ası'} else .001
    if s == ' ':
        value += .38 * fa + .32 * ro - .38 * cy
    else:
        value += fa * persian_spelling(s, t)
        value += cy * cyrillic_spelling(s, t)
        if t.isalpha() and all('LATIN' in unicodedata.name(c, '') for c in t):
            r = romanian_spelling(s, t)
            d = dutch_spelling(s, t)
            value += ro * r + nl * d
    return (doc, evidence, word), float(value)

