programs.sol:
"""Detect short spelling fragments that continue consonant-ending tokens.

The strongest context is a preceding c/C. Related consonants give weaker
responses; preceding vowels mildly suppress the same pattern. The clearest
continuations are o plus a nasal/liquid, single l/r, and digits after c/C.
C++/C# endings are negative; word boundaries largely switch the response
off. This is a spelling-based approximation, not a dictionary of token
activations.
"""
import unicodedata

READS = ()
VOWELS = set('aeiouyаеёиіоуыэюя')
LIQUIDS = set('lrлр')
NASALS = set('mnмн')


def context_strength(previous):
    if not previous:
        return 0.0
    last = unicodedata.normalize('NFKC', previous[-1])
    for letters, strength in (
        ('c', 1.0), ('C', 1.26), ('кКпП', 0.47),
        ('pPkKκπكک', 0.4), ('bBбБсС', 0.21),
        ('fFvVgGгГ', 0.17), ('hHхХ', 0.09),
    ):
        if last in letters:
            return strength
    return -0.06 if last.lower() in VOWELS else 0.0


def response(previous, token):
    gain = context_strength(previous)
    if token.rstrip() in ('++', '#'):
        is_c = previous and unicodedata.normalize('NFKC', previous[-1]) == 'C'
        return -0.33 if is_c else 0.0
    if len(token) == 1 and token in '⁰¹²³⁴⁵⁶⁷⁸⁹':
        return 0.1 * gain
    token = unicodedata.normalize('NFKC', token)
    if len(token) == 1 and token in '0123456789':
        return gain * max(0.14, 0.65 * 0.69 ** int(token))
    if not token.isalpha():
        return 0.0
    s = token.lower()
    n = len(s)
    first = s[0]
    rounded = first in 'oоο'
    liquid = first in LIQUIDS
    vowel = first in VOWELS
    baseline = -0.005
    if n == 1:
        value = 0.89 if rounded else 0.83 if liquid else 0.42 if vowel else 0.24
        if first == 'л':
            baseline, value = 0.14, 1.95
    else:
        second = s[1]
        nasal_next = second in NASALS
        liquid_next = second in LIQUIDS
        if rounded:
            if nasal_next:
                value = 1.4 * 0.65 ** min(n - 2, 2)
                baseline = 0.13 if n == 2 else 0.0
            elif liquid_next:
                value = max(0.2, 1.09 * 0.35 ** (n - 2))
            else:
                value = max(0.15, 0.55 * 0.55 ** (n - 2))
        elif liquid and second in VOWELS:
            value = 0.51 if n == 2 else 0.2 if n == 3 else 0.09
        elif vowel and liquid_next:
            value = 0.44 if n == 2 else 0.12 if n == 3 else 0.04
        elif vowel and nasal_next:
            value = 0.28 if n == 2 else 0.0
        elif vowel and second not in VOWELS:
            value = 0.0 if n == 2 else -0.1
        else:
            value = 0.15 if nasal_next else 0.1 if n == 2 else -0.02
    return baseline + gain * value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    return (document, token), float(response(previous, token))

