Training peaks included qualified libraries, switch labels and string-building
operations. These rules pulse on those constructions and common package/path
compounds, with negative pulses for selected declarations and type suffixes.
Unrecognized text is zero; short trailing context resets at document boundaries.
"""
import re

READS = ()
LIBRARY_ROOTS = {'org': .85, 'com': .20, 'java': .30, 'javax': .85,
                 'android': .35, 'androidx': .28, 'javafx': .55}
TYPE_PACKAGES = {'util', 'lang', 'awt', 'widget', 'view', 'scene', 'swing',
                 'annotation'}
OUTPUT_METHODS = {'print', 'println', 'WriteLine', 'Sprintf', 'Errorf'}
TYPE_SUFFIXES = {'Factory', 'Handler', 'Adapter', 'Storage', 'Listener'}


