    doc = prefix.document_ids[-1]
    prev, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word, text = token.strip(), tail + token
    value = 0.0
    # Qualified library names and output/serialization calls.
    if word.startswith('.') and word[1:].isidentifier():
        member, owner = word[1:], prev.strip().lstrip('(.')
        if re.search(r'\b(?:import|using)\s+(?:static\s+)?[\w.$]*$', tail):
            value = .15 if member[0].isupper() else .23
        if owner in LIBRARY_ROOTS:
            value = LIBRARY_ROOTS[owner]
        elif owner in TYPE_PACKAGES and member[0].isupper():
            value = .45
        if (owner, member) == ('org', 'apache'):
            value = 1.7
        elif (owner, member) == ('com', 'google'):
            value = .7
        if member in OUTPUT_METHODS or member in {'stringify', 'dumps', 'loads'}:
            value = .55
        elif member == 'get':
            value = -.09
    # String-building chains get a stronger append pulse.
    if word in {'.append', '.Append', 'append', 'Append'}:
        value = .3
        if prev.endswith(').') or re.search(
            r'(?:[Bb]uilder|\bsb)\.append$', text
        ):
            value = 1.3
