    if word in {'case', 'break', 'default'}:
        before = text[:-len(word)].replace('\\n', '\n').replace('\\t', '\t')
        line = re.sub(r'^\s*\d+\t', '', before.rsplit('\n', 1)[-1])
        if (not line.strip() and len(line) > 1) or re.search(r'[;{}]\s*$', before):
            value = 1.2 if word == 'case' else .45
    if re.search(r'(?:eslint-plugin|site-packages|internal/modules)$', text):
        value = 1.0
    elif text.endswith('AUTO_INCREMENT'):
        value = .9
    elif text.endswith(('node_modules', 'str_replace')):
        value = .17
    if word == 'void' or token in TYPE_SUFFIXES:
        value = -.3
    elif word == 'new' and prev.strip() in {'=', '::', 'return'}:
        value = -.24
    return (doc, token, text[-100:]), value

"""Approximate a detector for backslash-escaped punctuation.

An escaped double quote at a token's end gives the strongest response,
especially with a leading space. Quotes fused to closing punctuation are
weaker. Escaped apostrophes, backslashes and other symbols give smaller
responses. Plain text and backslash-letter escapes are approximated by zero.
Only the current token is inspected; no interpretation of the code is needed.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = 0.0
    if '\\"' in token:
        before, after = token.split('\\"', 1)
        if before.endswith('\\'):
            value = 1.4
        elif '"' in before or "'" in before:
            value = 2.6
        elif after.startswith((':', '\\')):
            value = 2.55
        elif after.startswith(','):
            value = 1.75 if '\\' in after else 2.2
        elif after:
            value = 2.0
        elif before.isspace():
            value = 5.6
        elif before.endswith(('.', '}')):
            value = 3.5
        else:
            value = 4.6 if before else 4.45
    elif "\\'" in token:
        before, after = token.split("\\'", 1)
        value = 1.2 if "'" in before + after else 2.7
    elif '\\\\' in token:
        value = 1.1 if token.count('\\') % 2 == 0 else 0.55
    elif '\\$' in token:
        value = 1.1 if token.startswith(' ') else 0.8
    else:
        for symbols, strength in (('_%-', 0.6), ('<>/', 0.85),
                                  ('[]()', 0.3), ('\n', 0.3)):
            if any('\\' + c in token for c in symbols):
                value = strength
                break
    return None, value

