cryptography and hashing vocabulary: strongest on hashing and encryption terms (hash, salt,
digest, cipher, AES, SHA, HMAC), weaker on the wider security and number-theory words
around them (prime, modulus, signature, password, key, random, bytes, encoding). Ordinary
words score zero. Its value is the typical activation of each word class."""
import re

READS = ()

CRYPTO = {"hash", "hashes", "hashed", "hashing", "hashlib", "hmac", "digest", "salt",
          "sha", "sha1", "sha256", "md5", "aes", "rsa", "crypto", "cryptographic",
          "cryptography", "cipher", "ciphertext", "encrypt", "encryption", "encrypted",
          "decrypt", "decryption", "plaintext", "pbkdf2", "bcrypt", "ssl", "tls", "checksum",
          "nonce"}
NUMBER_THEORY = {"prime", "primes", "mod", "modulo", "modulus", "modular", "gcd", "divisor",
                 "polynomial", "exponent", "generator", "divide", "divides", "division",
                 "factor", "factors"}
SECURITY = {"secret", "password", "passwords", "signature", "certificate", "random", "seed",
            "entropy", "byte", "bytes", "verify", "auth", "authenticate", "authentication",
            "key", "keys", "security", "sign", "encode", "encoding", "decode", "binary", "hex",
            "wallet", "bitcoin", "blockchain", "alice", "bob"}
TIER_VALUE = {"crypto": 1.4, "number": 0.45, "security": 0.45}

def tier_of(token):
    """The tier of the word in a token: a token may be a piece of a longer identifier,
    so each alphabetic piece of it is checked (`_hash`, `hashlib`, `SHA256`)."""
    pieces = re.findall(r"[a-z]+", token.lower())
    for piece in pieces:
        if piece in CRYPTO or piece.startswith(("hash", "crypt", "encrypt", "decrypt")):
            return "crypto"
    for piece in pieces:
        if piece in NUMBER_THEORY:
            return "number"
    for piece in pieces:
        if piece in SECURITY:
            return "security"
    return None

def step(carry, prefix, upstream):
    """The newest token's activation guess: its word tier's value, else 0."""
    return carry, TIER_VALUE.get(tier_of(prefix.token_strings[-1]), 0.0)

