"""Recognize cryptography and computer-security vocabulary.

Strong positive examples include hashing, salts, encryption, certificates,
public-key primes, and authentication. The rule follows split word-pieces and
predicts a small positive activation when a word first becomes recognizable;
it does not reproduce the component's full context-sensitive behavior.
"""

READS = ()

CRYPTO_ROOTS = (
    "crypt", "hash", "salt", "password", "encrypt", "decrypt", "cipher",
    "certificat", "authorit", "authent", "nonce", "digest", "signat",
    "keygen", "credential", "passphrase", "prime", "secure", "security",
    "brute", "verify", "attack", "signed",
)

CRYPTO_ACRONYMS = frozenset({
    "pb", "pbkdf", "pbkdf2", "sha", "sha1", "sha2", "sha224",
    "sha256", "sha384", "sha512", "rsa", "aes", "aes128", "aes192",
    "aes256", "des", "des3", "tls", "ssl", "ssh",
})

RELATED_TERMS = frozenset({
    "alice", "bob", "key", "keys", "mod", "modular", "base", "seed",
    "generator", "random", "exponent", "exponents", "byte", "bytes",
    "marshal",
})


def _word_so_far(old_word, piece):
    """Join word pieces, starting afresh at whitespace or punctuation."""
    if not piece:
        return ""
    if piece[0].isspace():
        raw = piece.strip()
    else:
        # A punctuation-led piece often begins a fresh code identifier.
        start = 0
        for i, char in enumerate(piece):
            if not char.isalnum():
                start = i + 1
        raw = piece[start:]
        if start == 0:
            raw = old_word + raw
    return "".join(char for char in raw if char.isalnum()).casefold()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, old_word = carry if carry is not None else (doc, "")
    if doc != old_doc:
        old_word = ""
    piece = prefix.token_strings[-1]
    continues_word = bool(piece) and piece[0].isalnum()
    word = _word_so_far(old_word, piece)

    matched = word in CRYPTO_ACRONYMS or any(
        root in word for root in CRYPTO_ROOTS
    )
    already_matched = continues_word and (
        old_word in CRYPTO_ACRONYMS or any(
            root in old_word for root in CRYPTO_ROOTS
        )
    )
    related = word in RELATED_TERMS
    already_related = continues_word and old_word in RELATED_TERMS
    if matched and not already_matched:
        value = 0.69
    elif related and not already_related:
        value = 0.69
    else:
        value = 0.0
    return (doc, word), float(value)

