import re

READS = ()

# The strongest family concerns reassessing and reworking something.
REWORKING = set('review reform repair'.split())
# Requests and provision, resistance and relief, information and intention.
SOCIAL_ACTIONS = set('appeal supply defense defend resist relief comfort concern'.split())
INFORMATION = set('detail inform intent'.split())


def bare_word(word):
    if word in REWORKING:
        return -0.84
    if word == 'demand':
        return -0.78
    if word in SOCIAL_ACTIONS:
        return -0.55
    if word in INFORMATION:
        return -0.55
    if word in ('renew', 'refresh', 'reward', 'deploy', 'conform', 'resort'):
        return -0.50
    if word in ('advice', 'counsel', 'consent', 'accord'):
        return -0.35
    return None


