    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('.-_/').lower()
    value = bare_word(word)
    if value is None:
        value = 0.002
        if (word.isascii() and word.isalpha() and len(word) > 4
                and word.startswith(('re', 'de', 'dis'))
                and len(re.findall('[aeiouy]+', word)) == 2):
            value = -0.035
        for ending, scale in (('s', 0.65), ('ed', 0.28), ('ing', 0.28)):
            if word.endswith(ending):
