        value = -1.05 if raw[:1].isspace() else -0.92
    if word == 'renew' and raw.strip()[:1].isupper():
        value = -0.82
    if word in ('details', 'detailed'):
        value = -0.20 if word == 'details' else -0.15
    if word in ('very', 'too'):
