        value = -0.28 if token.islower() else -0.62
    elif token == 'ence' and previous.strip() in {'H', 'h'}:
        # 'Hence' often arrives as H + ence.
        value = -1.48 if previous.strip() == 'H' else -1.2
    elif word in {'periment', 'periments', 'perimental'}:
        # Tokenized endings of the experiment word family.
        value = 0.8 if word == 'perimental' else 2.3
    elif word == 'strument':
        value = 2.36  # Instrument split after 'in'.
    elif word in RESULT_CUES:
        value = RESULT_CUES[word]
    elif word in EXPERIMENT_WORDS:
        value = EXPERIMENT_WORDS[word]
    else:
        value = INSTRUMENT_WORDS.get(word, 0.0)
    return (doc, raw), float(value)

programs.luna:
"""Estimate activation for consequence markers and experiment-related words."""
READS = ()

CONNECTORS = {
    "thus": -3.5,
    "therefore": -1.1,
    "hence": -1.8,
    "consequently": -0.8,
    "accordingly": -0.8,
    "donc": -0.6,
    "así": -0.7,
    "因此": -1.2,
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw.casefold()
    if word.startswith("experiment"):
        return None, 1.6
    if word == "so":
        return None, -0.68 if raw[:1].isupper() else -0.30
    return None, CONNECTORS.get(word, 0.0)

programs.haiku:
"""Fires on English adjectives of size, degree, importance and quality (big, high, large,
small, grand, special, important...), and on their Chinese/Japanese/Italian equivalents.
It reads only the current token: each word has a fixed strength, and every other token is 0."""
READS = ()

# Strength of the response to each word, roughly in nats of the component's own units.
STRONG = {"grand": 4.5, "big": 2.1, "special": 2.0, "grande": 1.8, "伟大": 2.2, "大": 1.0}
MEDIUM = {
    "high": 1.4, "deep": 1.2, "wide": 1.1, "large": 1.1, "important": 1.1, "small": 1.0,
    "main": 0.9, "great": 0.8, "strong": 0.9, "tight": 1.1, "broad": 1.0, "bright": 0.9,
    "sharp": 0.8, "thick": 0.8, "tall": 0.8, "short": 0.8, "early": 0.8, "hot": 0.8,
    "重要": 1.3, "小": 0.8, "特": 0.8,
}
WEAK = {
    "long": 0.7, "little": 0.7, "good": 0.7, "fast": 0.7, "quick": 0.7, "old": 0.6,
    "young": 0.6, "low": 0.6, "cold": 0.6, "soft": 0.6, "heavy": 0.7, "vast": 0.6,
    "huge": 0.6, "warm": 0.6, "slow": 0.5, "late": 0.4, "bad": 0.35, "hard": 0.4,
    "thin": 0.5, "higher": 0.3, "major": 0.4, "significant": 0.3,
}
STRENGTH = {**STRONG, **MEDIUM, **WEAK}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return carry, float(STRENGTH.get(word, 0.0))

programs.luna:
"""Recognize common written abbreviations ending in a period."""
READS = ()

ABBREVIATIONS = {
    "mr", "mrs", "ms", "dr", "prof", "rev", "sr", "jr",
    "no", "st", "vs", "v", "p", "pp", "vol", "i.e", "e.g",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]

    value = 0.0
    if token == ".":
        words = tail.rstrip().split()
        if words:
            last = words[-1].strip('"\'()[]{}:,;!?').lower()
            previous = words[-2].strip('"\'()[]{}:,;!?').lower() if len(words) > 1 else ""
            if last in ABBREVIATIONS or (last == "al" and previous == "et"):
                value = 0.9

    return (doc, (tail + token)[-80:]), value
